-- =====================================================================================================
-- supabase-schema.sql
-- =====================================================================================================
-- Modaat shared order-management database
-- Run in the Supabase SQL Editor for the new project.
-- No credentials, API keys, or user approvals are included in this file.

create schema if not exists private;
revoke all on schema private from public, anon, authenticated;
grant usage on schema private to authenticated;

-- Only project owners/operators using the SQL Editor may manage this allowlist.
-- Never grant this table to anon or authenticated application users.
create table if not exists private.approved_users (
  user_id uuid primary key references auth.users (id) on delete cascade,
  approved_at timestamptz not null default now(),
  approved_by uuid references auth.users (id) on delete set null
);

alter table private.approved_users enable row level security;
alter table private.approved_users force row level security;
revoke all on table private.approved_users from public, anon, authenticated;

-- A fixed search_path and schema-qualified table reference prevent object-shadowing.
create or replace function private.is_approved_user()
returns boolean
language sql
stable
security definer
set search_path = ''
as $function$
  select
    (select auth.uid()) is not null
    and exists (
      select 1
      from private.approved_users as allowed
      where allowed.user_id = (select auth.uid())
    );
$function$;

revoke all on function private.is_approved_user() from public, anon;
grant execute on function private.is_approved_user() to authenticated;

-- The browser uses this RPC to distinguish an approved user from the empty
-- result that RLS intentionally returns to an unapproved authenticated user.
create or replace function public.current_user_is_approved()
returns boolean
language sql
stable
security definer
set search_path = ''
as $function$
  select private.is_approved_user();
$function$;

revoke all on function public.current_user_is_approved() from public, anon;
grant execute on function public.current_user_is_approved() to authenticated;

create table if not exists public.clients (
  id text primary key,
  name text not null check (length(btrim(name)) > 0),
  phone text,
  email text,
  created_at timestamptz not null default now()
);

create table if not exists public.orders (
  id text primary key,
  client_id text not null
    references public.clients (id) on update cascade on delete restrict,
  publication_date date not null,
  section text not null check (length(btrim(section)) > 0),
  amount numeric(10, 2) not null check (amount > 0 and amount <= 99999999),
  payment_status text not null default 'pending'
    check (payment_status in ('paid', 'pending')),
  notes text not null default '',
  created_at timestamptz not null default now()
);

-- This table is an append-only ledger for actual payments recorded in the future.
-- Existing local orders have a status, but no payment-event history; do not
-- fabricate payment records when importing them.
create table if not exists public.payments (
  id uuid primary key default gen_random_uuid(),
  order_id text not null
    references public.orders (id) on update cascade on delete restrict,
  amount numeric(10, 2) not null check (amount > 0 and amount <= 99999999),
  paid_at timestamptz not null default now(),
  payment_method text,
  reference text,
  notes text not null default '',
  created_by uuid not null default auth.uid()
    references auth.users (id) on delete restrict,
  created_at timestamptz not null default now()
);

create index if not exists orders_client_id_idx on public.orders (client_id);
create index if not exists orders_publication_date_idx on public.orders (publication_date);
create index if not exists orders_payment_status_idx on public.orders (payment_status);
create index if not exists payments_order_id_paid_at_idx on public.payments (order_id, paid_at);

grant usage on schema public to authenticated;

alter table public.clients enable row level security;
alter table public.clients force row level security;
alter table public.orders enable row level security;
alter table public.orders force row level security;
alter table public.payments enable row level security;
alter table public.payments force row level security;

revoke all on table public.clients, public.orders, public.payments
  from public, anon, authenticated;
grant select, insert, update, delete on table public.clients, public.orders
  to authenticated;
grant select, insert on table public.payments to authenticated;

drop policy if exists "approved users can manage clients" on public.clients;
create policy "approved users can manage clients"
  on public.clients
  for all
  to authenticated
  using ((select private.is_approved_user()))
  with check ((select private.is_approved_user()));

drop policy if exists "approved users can manage orders" on public.orders;
create policy "approved users can manage orders"
  on public.orders
  for all
  to authenticated
  using ((select private.is_approved_user()))
  with check ((select private.is_approved_user()));

drop policy if exists "approved users can read payments" on public.payments;
create policy "approved users can read payments"
  on public.payments
  for select
  to authenticated
  using ((select private.is_approved_user()));

drop policy if exists "approved users can record payments" on public.payments;
create policy "approved users can record payments"
  on public.payments
  for insert
  to authenticated
  with check (
    (select private.is_approved_user())
    and created_by = (select auth.uid())
  );

comment on table private.approved_users is
  'Manually managed allowlist. Add only invited, explicitly authorized auth.users IDs.';
comment on table public.clients is
  'Clients shared with every explicitly approved application user.';
comment on table public.orders is
  'Orders retain the current application payment_status and legacy text IDs.';
comment on table public.payments is
  'Append-only payment-event ledger; updates and deletes are intentionally denied.';


-- =====================================================================================================
-- supabase-reliability-migration.sql
-- =====================================================================================================
-- Non-destructive support for safe concurrent edits and Realtime refresh.
-- Run in the Supabase SQL Editor as the project owner before deploying app.js.
-- This does not update, delete, or import client/order records and does not
-- change table RLS policies or table grants.

begin;

alter table public.clients
  add column if not exists updated_at timestamptz not null default pg_catalog.now();

alter table public.orders
  add column if not exists updated_at timestamptz not null default pg_catalog.now();

create or replace function public.touch_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $function$
begin
  new.updated_at := pg_catalog.clock_timestamp();
  return new;
end;
$function$;

revoke all on function public.touch_updated_at() from public, anon, authenticated;

drop trigger if exists clients_touch_updated_at on public.clients;
create trigger clients_touch_updated_at
  before update on public.clients
  for each row execute function public.touch_updated_at();

drop trigger if exists orders_touch_updated_at on public.orders;
create trigger orders_touch_updated_at
  before update on public.orders
  for each row execute function public.touch_updated_at();

do $migration$
begin
  if not exists (
    select 1 from pg_catalog.pg_publication where pubname = 'supabase_realtime'
  ) then
    raise exception 'Supabase Realtime publication is unavailable; enable Realtime before running this migration.';
  end if;

  if not exists (
    select 1 from pg_catalog.pg_publication_tables
    where pubname = 'supabase_realtime'
      and schemaname = 'public'
      and tablename = 'clients'
  ) then
    execute 'alter publication supabase_realtime add table public.clients';
  end if;

  if not exists (
    select 1 from pg_catalog.pg_publication_tables
    where pubname = 'supabase_realtime'
      and schemaname = 'public'
      and tablename = 'orders'
  ) then
    execute 'alter publication supabase_realtime add table public.orders';
  end if;
end;
$migration$;

commit;


-- =====================================================================================================
-- supabase-business-upgrade.sql
-- =====================================================================================================
-- Modaat business upgrade: additive schema and transactional operations.
-- REVIEW BEFORE RUNNING. This file was not executed in Supabase.
-- Expected baseline: supabase-schema.sql plus updated_at columns/triggers from
-- supabase-reliability-migration.sql. Run only after a read-only preflight and
-- backup of the live database. No client/order rows are deleted or re-imported.
-- PHASE 1 only: this migration intentionally preserves the existing direct
-- orders/payments write grants so the current UI does not abruptly lose writes.
-- Deploy and validate the RPC-based UI, then run
-- supabase-business-upgrade-cutover.sql during a short write-freeze to revoke
-- those grants. Never run the cutover while the current direct-write UI is live.

begin;

do $preflight$
declare
  v_has_order_number_conflict boolean;
begin
  if current_setting('server_version_num')::integer < 150000 then
    raise exception 'This migration requires PostgreSQL 15 or newer for security-invoker reporting views.';
  end if;
  if pg_catalog.to_regclass('public.clients') is null
     or pg_catalog.to_regclass('public.orders') is null
     or pg_catalog.to_regclass('public.payments') is null then
    raise exception 'Expected public.clients, public.orders, and public.payments. Stop and review the live schema before migration.';
  end if;
  if pg_catalog.to_regclass('private.approved_users') is null
     or pg_catalog.to_regprocedure('private.is_approved_user()') is null
     or pg_catalog.to_regprocedure('public.current_user_is_approved()') is null then
    raise exception 'The approved-user allowlist/RPC is missing. Install and verify the existing Auth/RLS setup first.';
  end if;
  if not exists (
    select 1 from pg_catalog.pg_attribute
    where attrelid = 'public.clients'::regclass
      and attname = 'created_at' and not attisdropped
  ) or not exists (
    select 1 from pg_catalog.pg_attribute
    where attrelid = 'public.orders'::regclass
      and attname = 'created_at' and not attisdropped
  ) then
    raise exception 'The existing created_at columns are missing. Stop and adapt this migration to the live schema.';
  end if;
  if not exists (
    select 1 from pg_catalog.pg_attribute
    where attrelid = 'public.orders'::regclass
      and attname = 'amount' and not attisdropped
  ) or not exists (
    select 1 from pg_catalog.pg_attribute
    where attrelid = 'public.orders'::regclass
    and attname = 'payment_status' and not attisdropped
  ) or not exists (
    select 1 from pg_catalog.pg_attribute
    where attrelid = 'public.orders'::regclass
    and attname = 'client_id' and not attisdropped
  ) or not exists (
    select 1 from pg_catalog.pg_attribute
    where attrelid = 'public.orders'::regclass
    and attname = 'publication_date' and not attisdropped
  ) or not exists (
    select 1 from pg_catalog.pg_attribute
    where attrelid = 'public.orders'::regclass
    and attname = 'section' and not attisdropped
  ) or not exists (
    select 1 from pg_catalog.pg_attribute
    where attrelid = 'public.payments'::regclass
    and attname = 'order_id' and not attisdropped
  ) or not exists (
    select 1 from pg_catalog.pg_attribute
    where attrelid = 'public.payments'::regclass
    and attname = 'amount' and not attisdropped
  ) then
    raise exception 'Required legacy order/payment columns are missing. Stop and adapt this migration.';
  end if;
  if exists (
    select 1
    from (values
      ('public.clients'::regclass, 'id', 'text'::regtype),
      ('public.clients'::regclass, 'name', 'text'::regtype),
      ('public.clients'::regclass, 'created_at', 'timestamp with time zone'::regtype),
      ('public.clients'::regclass, 'updated_at', 'timestamp with time zone'::regtype),
      ('public.orders'::regclass, 'id', 'text'::regtype),
      ('public.orders'::regclass, 'client_id', 'text'::regtype),
      ('public.orders'::regclass, 'payment_status', 'text'::regtype),
      ('public.payments'::regclass, 'order_id', 'text'::regtype),
      ('public.orders'::regclass, 'amount', 'numeric'::regtype),
      ('public.payments'::regclass, 'amount', 'numeric'::regtype),
      ('public.orders'::regclass, 'publication_date', 'date'::regtype),
      ('public.orders'::regclass, 'section', 'text'::regtype),
      ('public.orders'::regclass, 'created_at', 'timestamp with time zone'::regtype),
      ('public.orders'::regclass, 'updated_at', 'timestamp with time zone'::regtype)
    ) as expected_columns(relation_id, column_name, data_type)
    where not exists (
      select 1
      from pg_catalog.pg_attribute as actual
      where actual.attrelid = expected_columns.relation_id
        and actual.attname = expected_columns.column_name
        and actual.atttypid = expected_columns.data_type
        and not actual.attisdropped
    )
  ) then
    raise exception 'Legacy table column types differ from the expected text/numeric/date schema. Review before migration.';
  end if;
  if exists (
    select 1
    from (values
      ('public.clients'::regclass, 'id'),
      ('public.clients'::regclass, 'name'),
      ('public.clients'::regclass, 'created_at'),
      ('public.clients'::regclass, 'updated_at'),
      ('public.orders'::regclass, 'id'),
      ('public.orders'::regclass, 'client_id'),
      ('public.orders'::regclass, 'publication_date'),
      ('public.orders'::regclass, 'section'),
      ('public.orders'::regclass, 'amount'),
      ('public.orders'::regclass, 'payment_status'),
      ('public.orders'::regclass, 'created_at'),
      ('public.orders'::regclass, 'updated_at'),
      ('public.payments'::regclass, 'order_id'),
      ('public.payments'::regclass, 'amount')
    ) as required_columns(relation_id, column_name)
    where not exists (
      select 1
      from pg_catalog.pg_attribute as actual
      where actual.attrelid = required_columns.relation_id
        and actual.attname = required_columns.column_name
        and actual.attnotnull
        and not actual.attisdropped
    )
  ) then
    raise exception 'A required legacy column is nullable. Review the live schema before migration.';
  end if;
  if not exists (
    select 1 from pg_catalog.pg_constraint
    where conrelid = 'public.orders'::regclass
      and conname = 'orders_amount_check'
      and contype = 'c'
  ) then
    raise exception 'Expected the original positive-amount constraint orders_amount_check. Inspect constraints before migration.';
  end if;
  if not exists (
    select 1
    from pg_catalog.pg_constraint as constraints
    where constraints.conrelid = 'public.orders'::regclass
      and constraints.confrelid = 'public.clients'::regclass
      and constraints.contype = 'f'
      and constraints.conkey = array[(
        select attribute.attnum
        from pg_catalog.pg_attribute as attribute
        where attribute.attrelid = 'public.orders'::regclass
          and attribute.attname = 'client_id'
          and not attribute.attisdropped
      )]::smallint[]
      and constraints.confkey = array[(
        select attribute.attnum
        from pg_catalog.pg_attribute as attribute
        where attribute.attrelid = 'public.clients'::regclass
          and attribute.attname = 'id'
          and not attribute.attisdropped
      )]::smallint[]
  ) or not exists (
    select 1
    from pg_catalog.pg_constraint as constraints
    where constraints.conrelid = 'public.payments'::regclass
      and constraints.confrelid = 'public.orders'::regclass
      and constraints.contype = 'f'
      and constraints.conkey = array[(
        select attribute.attnum
        from pg_catalog.pg_attribute as attribute
        where attribute.attrelid = 'public.payments'::regclass
          and attribute.attname = 'order_id'
          and not attribute.attisdropped
      )]::smallint[]
      and constraints.confkey = array[(
        select attribute.attnum
        from pg_catalog.pg_attribute as attribute
        where attribute.attrelid = 'public.orders'::regclass
          and attribute.attname = 'id'
          and not attribute.attisdropped
      )]::smallint[]
  ) then
    raise exception 'Expected client/order and payment/order foreign keys are missing or target different columns.';
  end if;
  if not exists (
    select 1 from pg_catalog.pg_attribute
    where attrelid = 'public.clients'::regclass
      and attname = 'updated_at' and not attisdropped
  ) or not exists (
    select 1 from pg_catalog.pg_attribute
    where attrelid = 'public.orders'::regclass
      and attname = 'updated_at' and not attisdropped
  ) then
    raise exception 'Run and verify supabase-reliability-migration.sql first; updated_at is required for conflict protection.';
  end if;
  if not exists (
    select 1 from pg_catalog.pg_class
    where oid = 'public.clients'::regclass
      and relrowsecurity and relforcerowsecurity
  ) or not exists (
    select 1 from pg_catalog.pg_class
    where oid = 'public.orders'::regclass
      and relrowsecurity and relforcerowsecurity
  ) or not exists (
    select 1 from pg_catalog.pg_class
    where oid = 'public.payments'::regclass
      and relrowsecurity and relforcerowsecurity
  ) then
    raise exception 'RLS and FORCE ROW LEVEL SECURITY must already be enabled on clients, orders, and payments.';
  end if;
  if not exists (
    select 1 from pg_catalog.pg_policies
    where schemaname = 'public'
      and tablename = 'clients'
      and 'authenticated' = any(roles)
      and coalesce(qual, '') like '%is_approved_user%'
  ) or not exists (
    select 1 from pg_catalog.pg_policies
    where schemaname = 'public'
      and tablename = 'orders'
      and 'authenticated' = any(roles)
      and coalesce(qual, '') like '%is_approved_user%'
  ) or not exists (
    select 1 from pg_catalog.pg_policies
    where schemaname = 'public'
      and tablename = 'payments'
      and 'authenticated' = any(roles)
      and coalesce(qual, '') like '%is_approved_user%'
  ) then
    raise exception 'Approved-user RLS policies are missing on clients, orders, or payments.';
  end if;
  if has_table_privilege('anon', 'public.clients', 'SELECT')
     or has_table_privilege('anon', 'public.orders', 'SELECT')
     or has_table_privilege('anon', 'public.payments', 'SELECT') then
    raise exception 'The anon role has direct table access; review grants before migration.';
  end if;
  if exists (
    select 1 from public.orders
    where payment_status is null
       or payment_status not in ('paid', 'pending')
  ) then
    raise exception 'Legacy orders contain an unknown payment_status. Review them before migration.';
  end if;
  if exists (
    select 1 from public.orders
    where amount is null or amount < 0 or amount > 99999999
  ) then
    raise exception 'Legacy orders contain a null or out-of-range amount. Reconcile them before migration.';
  end if;
  if exists (
    select 1
    from public.orders as orders
    left join public.clients as clients on clients.id = orders.client_id
    where clients.id is null
  ) then
    raise exception 'Orphan order rows exist. Reconcile client links before migration.';
  end if;
  if exists (
    select 1
    from public.payments as payments
    left join public.orders as orders on orders.id = payments.order_id
    where orders.id is null
  ) then
    raise exception 'Orphan payment rows exist. Reconcile them before migration.';
  end if;
  if exists (
    select 1
    from public.orders as orders
    join public.payments as payments on payments.order_id = orders.id
    where orders.amount = 0
  ) then
    raise exception 'Zero-amount orders have payment rows. Reconcile them before migration.';
  end if;
  if exists (
    select 1
    from pg_catalog.pg_attribute
    where attrelid = 'public.orders'::regclass
      and attname = 'order_number'
      and not attisdropped
  ) then
    if exists (
    select 1
    from pg_catalog.pg_attribute
    where attrelid = 'public.orders'::regclass
      and attname = 'order_number'
      and atttypid <> 'bigint'::regtype
      and not attisdropped
    ) then
    raise exception 'Existing order_number has an unexpected type. Review it before migration.';
    end if;
    execute $check_numbers$
    select exists (
      select 1
        from public.orders
        where order_number is not null and order_number <= 0
      ) or exists (
        select 1
        from public.orders
        where order_number is not null
        group by order_number
        having count(*) > 1
      ) or (
        coalesce(max(order_number), 0)::numeric
          + count(*) filter (where order_number is null)
          >= 9223372036854775807::numeric
      )
      from public.orders
    $check_numbers$ into v_has_order_number_conflict;
    if v_has_order_number_conflict then
      raise exception 'Existing order numbers are non-positive, duplicated, or would overflow during assignment. Reconcile them before migration.';
    end if;
  end if;
end;
$preflight$;

create schema if not exists private;
revoke all on schema private from public, anon, authenticated;
grant usage on schema private to authenticated;

alter table public.clients
  add column if not exists internal_notes text not null default '',
  add column if not exists joined_at date;

update public.clients
set joined_at = created_at::date
where joined_at is null;

alter table public.clients
  alter column joined_at set default current_date,
  alter column joined_at set not null;

alter table public.orders
  add column if not exists order_number bigint,
  add column if not exists entered_at date,
  add column if not exists entered_by uuid references auth.users (id) on delete set null,
  add column if not exists entered_by_name text,
  add column if not exists sheet_number text,
  add column if not exists product_id uuid,
  add column if not exists product_name_snapshot text,
  add column if not exists product_dimensions_snapshot text,
  add column if not exists product_price_snapshot numeric(12, 2),
  add column if not exists product_credit_cost_snapshot numeric(12, 2),
  add column if not exists billing_mode text not null default 'legacy',
  add column if not exists cash_amount_before_vat numeric(12, 2),
  add column if not exists credits_used numeric(12, 2),
  add column if not exists vat_rate_snapshot numeric(5, 4);

update public.orders
set entered_at = created_at::date
where entered_at is null;

alter table public.orders
  alter column entered_at set default current_date,
  alter column entered_at set not null;

-- Keep the existing text ID as the immutable record key. Assign the separate
-- business-facing sequence only to rows that do not already have a number.
-- Business order numbers start at 22000 (5 digits) and continue from any higher existing number.
with current_max as (
  select greatest(coalesce(max(order_number), 0), 21999) as last_number
  from public.orders
),
numbered_orders as (
  select orders.id,
         current_max.last_number
           + row_number() over (order by orders.created_at, orders.id) as assigned_number
  from public.orders
  cross join current_max
  where orders.order_number is null
)
update public.orders as existing
set order_number = numbered_orders.assigned_number
from numbered_orders
where existing.id = numbered_orders.id;

create table if not exists private.order_number_counters (
  counter_name text primary key,
  last_number bigint not null check (last_number >= 0)
);

insert into private.order_number_counters (counter_name, last_number)
select 'orders', coalesce(max(order_number), 0)
from public.orders
on conflict (counter_name) do update
  set last_number = greatest(
    private.order_number_counters.last_number,
    excluded.last_number
  );

alter table private.order_number_counters enable row level security;
alter table private.order_number_counters force row level security;
revoke all on table private.order_number_counters from public, anon, authenticated;

create or replace function private.assign_business_order_number()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
begin
  update private.order_number_counters
  set last_number = last_number + 1
  where counter_name = 'orders'
    and last_number < 9223372036854775807
  returning last_number into new.order_number;

  if new.order_number is null then
    raise exception 'Order number counter is unavailable or exhausted.';
  end if;
  return new;
end;
$function$;

revoke all on function private.assign_business_order_number() from public, anon, authenticated;

drop trigger if exists orders_assign_business_order_number on public.orders;
create trigger orders_assign_business_order_number
  before insert on public.orders
  for each row execute function private.assign_business_order_number();

alter table public.orders
  alter column order_number set not null;

alter table public.orders
  add constraint orders_business_order_number_positive_check
  check (order_number > 0);

create unique index if not exists orders_order_number_uidx
  on public.orders (order_number);

create index if not exists orders_sheet_publication_date_idx
  on public.orders (sheet_number, publication_date desc)
  where sheet_number is not null;

create index if not exists orders_product_id_idx
  on public.orders (product_id)
  where product_id is not null;

-- The baseline schema has the autogenerated orders_amount_check (> 0).
-- Credit-funded rows store zero cash in the legacy amount column.
alter table public.orders
  drop constraint if exists orders_amount_check,
  drop constraint if exists orders_amount_nonnegative_check,
  drop constraint if exists orders_business_billing_check,
  drop constraint if exists orders_business_billing_mode_check,
  add constraint orders_amount_nonnegative_check
    check (amount >= 0 and amount <= 99999999),
  add constraint orders_business_billing_mode_check
    check (billing_mode in ('legacy', 'cash', 'credits')),
  add constraint orders_business_billing_check
    check (
      (billing_mode = 'legacy'
        and cash_amount_before_vat is null
        and credits_used is null)
      or
      (billing_mode = 'cash'
        and cash_amount_before_vat > 0
        and credits_used is null
        and vat_rate_snapshot between 0 and 1
        and amount > 0)
      or
      (billing_mode = 'credits'
        and cash_amount_before_vat is null
        and credits_used > 0
        and credits_used = round(credits_used, 2)
        and amount = 0)
    );

