create or replace function public.set_business_vat_rate(p_vat_rate numeric)
returns void
language plpgsql
security definer
set search_path = ''
as $function$
begin
  if auth.uid() is null or not private.is_approved_user() then
    raise exception 'החשבון אינו מורשה לבצע פעולה זו.';
  end if;
  if p_vat_rate is null or p_vat_rate < 0 or p_vat_rate > 1 then
    raise exception 'שיעור המע"מ חייב להיות בין 0%% ל-100%%.';
  end if;
  update public.business_settings
  set vat_rate = p_vat_rate, updated_by = auth.uid()
  where singleton;
end;
$function$;

revoke all on function public.set_business_vat_rate(numeric) from public, anon;
grant execute on function public.set_business_vat_rate(numeric) to authenticated;

create or replace function public.create_orders_batch(
  p_client_id text,
  p_orders jsonb,
  p_idempotency_key uuid
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_cached jsonb;
  v_row jsonb;
  v_product public.product_catalog%rowtype;
  v_client public.clients%rowtype;
  v_vat numeric(5, 4);
  v_cash numeric;
  v_credits numeric;
  v_amount numeric(12, 2);
  v_status text;
  v_id text;
  v_order_number bigint;
  v_obligation_id uuid;
  v_result jsonb := '[]'::jsonb;
  v_actor_label text;
  v_balance numeric;
  v_count integer := 0;
  v_sheet text;
  v_publication_date date;
  v_due_on date;
begin
  if auth.uid() is null or not private.is_approved_user() then
    raise exception 'החשבון אינו מורשה לבצע פעולה זו.';
  end if;
  if p_client_id is null or p_orders is null
     or jsonb_typeof(p_orders) <> 'array'
     or jsonb_array_length(p_orders) = 0
     or jsonb_array_length(p_orders) > 250 then
    raise exception 'יש לבחור לקוח ולהוסיף בין הזמנה אחת ל-250 הזמנות.';
  end if;

  v_cached := private.claim_business_operation(
    p_idempotency_key, 'create_orders_batch',
    pg_catalog.md5(p_client_id || ':' || p_orders::text)
  );
  if v_cached is not null then
    return v_cached;
  end if;

  select * into v_client
  from public.clients
  where id = p_client_id
  for update;
  if not found then
    raise exception 'הלקוח לא נמצא.';
  end if;

  select vat_rate into v_vat
  from public.business_settings
  where singleton;
  if v_vat is null then
    raise exception 'הגדרת המע"מ חסרה.';
  end if;

  v_actor_label := coalesce(
    nullif(auth.jwt() -> 'user_metadata' ->> 'full_name', ''),
    nullif(auth.jwt() -> 'user_metadata' ->> 'name', ''),
    nullif(auth.jwt() ->> 'email', ''),
    'משתמשת'
  );

  for v_row in select value from jsonb_array_elements(p_orders)
  loop
    v_count := v_count + 1;
    if jsonb_typeof(v_row) <> 'object' then
      raise exception 'שורת הזמנה % אינה תקינה.', v_count;
    end if;

    v_cash := nullif(v_row ->> 'cash_amount_before_vat', '')::numeric;
    if v_cash is not null
       and (v_cash <= 0 or v_cash > 99999999 or round(v_cash, 2) <> v_cash) then
      raise exception 'המחיר בשורה % חייב להיות חיובי, עד 99,999,999 ש"ח, ובדיוק שתי ספרות אחרי הנקודה.', v_count;
    end if;
    v_credits := nullif(v_row ->> 'credits_used', '')::numeric;
    if (v_cash is not null and v_cash <= 0)
       or (v_credits is not null and
         (v_credits <= 0 or round(v_credits, 2) <> v_credits))
       or ((v_cash is null) = (v_credits is null)) then
      raise exception 'בכל שורה יש למלא בדיוק ערך חיובי אחד: מחיר לפני מע"מ או קרדיטים.';
    end if;

    v_sheet := nullif(btrim(v_row ->> 'sheet_number'), '');
    if v_sheet is null or length(v_sheet) > 80 then
      raise exception 'יש להזין מספר גיליון תקין בשורה %.', v_count;
    end if;
    if nullif(v_row ->> 'publication_date', '') is null then
      raise exception 'יש להזין תאריך פרסום בשורה %.', v_count;
    end if;
    v_publication_date := (v_row ->> 'publication_date')::date;
    v_status := coalesce(v_row ->> 'payment_status', 'pending');
    if v_status not in ('paid', 'pending') then
      raise exception 'סטטוס התשלום בשורה % אינו תקין.', v_count;
    end if;
    v_due_on := nullif(v_row ->> 'due_on', '')::date;

    select * into v_product
    from public.product_catalog
    where id = (v_row ->> 'product_id')::uuid
      and is_active
    for share;
    if not found then
      raise exception 'המוצר בשורה % אינו קיים או אינו פעיל.', v_count;
    end if;
    if v_product.base_price_before_vat is null or v_product.credit_cost is null then
      raise exception 'המוצר בשורה % חסר מחיר או עלות קרדיטים ממקור מאומת.', v_count;
    end if;
    if v_cash is not null then
      v_amount := round(v_cash * (1 + v_vat), 2);
    else
      v_amount := 0;
      v_status := 'paid';
    end if;

    insert into public.orders (
      id, client_id, publication_date, section, amount, payment_status, notes,
      entered_at, entered_by, entered_by_name, sheet_number, product_id,
      product_name_snapshot, product_dimensions_snapshot,
      product_price_snapshot, product_credit_cost_snapshot, billing_mode,
      cash_amount_before_vat, credits_used, vat_rate_snapshot
    )
    values (
      'o-' || gen_random_uuid()::text,
      p_client_id,
      v_publication_date,
      v_product.name,
      v_amount,
      v_status,
      coalesce(v_row ->> 'notes', ''),
      current_date,
      auth.uid(),
      v_actor_label,
      v_sheet,
      v_product.id,
      v_product.name,
      v_product.dimensions,
      v_product.base_price_before_vat,
      v_product.credit_cost,
      case when v_cash is not null then 'cash' else 'credits' end,
      v_cash,
      v_credits,
      case when v_cash is not null then v_vat else null end
    )
    returning id, order_number into v_id, v_order_number;

    if v_credits is not null then
      insert into public.credit_ledger (
        client_id, delta, entry_type, order_id, reason, idempotency_key, created_by
      )
      values (
        p_client_id, -v_credits, 'order_consumption', v_id,
        'ניצול קרדיטים בהזמנה ' || v_order_number,
        gen_random_uuid(), auth.uid()
      );
      select coalesce(sum(delta), 0) into v_balance
      from public.credit_ledger
      where client_id = p_client_id;
      v_result := v_result || jsonb_build_array(jsonb_build_object(
        'id', v_id, 'order_number', v_order_number,
        'billing_mode', 'credits', 'credit_balance_after', v_balance
      ));
    else
      insert into public.financial_obligations (
        order_id, amount_due, due_on, status, paid_at, paid_by, created_by
      )
      values (
        v_id, v_amount, v_due_on, v_status,
        case when v_status = 'paid' then pg_catalog.now() else null end,
        case when v_status = 'paid' then auth.uid() else null end,
        auth.uid()
      )
      returning id into v_obligation_id;

      if v_status = 'paid' then
        insert into public.business_payment_events (
          obligation_id, event_type, amount, notes, idempotency_key, created_by
        )
        values (
          v_obligation_id, 'payment', v_amount,
          'סומן כשולם בעת יצירת ההזמנה',
          gen_random_uuid(), auth.uid()
        );
      end if;
      v_result := v_result || jsonb_build_array(jsonb_build_object(
        'id', v_id, 'order_number', v_order_number,
        'billing_mode', 'cash', 'gross_amount', v_amount,
        'obligation_id', v_obligation_id
      ));
    end if;
  end loop;

  update private.business_operations
  set response = v_result
  where idempotency_key = p_idempotency_key;

  return v_result;
end;
$function$;

revoke all on function public.create_orders_batch(text, jsonb, uuid) from public, anon;
grant execute on function public.create_orders_batch(text, jsonb, uuid) to authenticated;

create or replace function public.purchase_customer_package(
  p_client_id text,
  p_package_id uuid,
  p_custom_name text,
  p_credits numeric,
  p_term_months integer,
  p_price_before_vat numeric,
  p_starts_on date,
  p_ends_on date,
  p_installments jsonb,
  p_benefits jsonb,
  p_notes text,
  p_idempotency_key uuid
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_cached jsonb;
  v_client public.clients%rowtype;
  v_template public.package_catalog%rowtype;
  v_package_name text;
  v_credits numeric;
  v_term integer;
  v_price numeric;
  v_benefits jsonb;
  v_vat numeric(5, 4);
  v_count integer;
  v_sum numeric;
  v_gross numeric(12, 2);
  v_package_id uuid;
  v_item jsonb;
  v_installment_id uuid;
  v_obligation_id uuid;
  v_index integer := 0;
  v_result jsonb := '[]'::jsonb;
  v_actor_label text;
begin
  if auth.uid() is null or not private.is_approved_user() then
    raise exception 'החשבון אינו מורשה לבצע פעולה זו.';
  end if;
  if p_installments is null
     or jsonb_typeof(p_installments) <> 'array'
     or jsonb_array_length(p_installments) < 1
     or jsonb_array_length(p_installments) > 60 then
    raise exception 'יש להגדיר בין תשלום אחד ל-60 תשלומים.';
  end if;
  if p_starts_on is null or p_ends_on is null or p_ends_on < p_starts_on then
    raise exception 'טווח תאריכי החבילה אינו תקין.';
  end if;

  v_cached := private.claim_business_operation(
    p_idempotency_key, 'purchase_customer_package',
    pg_catalog.md5(concat_ws(':', p_client_id, p_package_id, p_custom_name,
      p_credits, p_term_months, p_price_before_vat, p_starts_on, p_ends_on,
      p_installments::text, p_benefits::text, p_notes))
  );
  if v_cached is not null then
    return v_cached;
  end if;

  select * into v_client from public.clients
  where id = p_client_id for update;
  if not found then
    raise exception 'הלקוח לא נמצא.';
  end if;

  select vat_rate into v_vat
  from public.business_settings where singleton;
  if v_vat is null then
    raise exception 'הגדרת המע"מ חסרה.';
  end if;

  if p_package_id is not null then
    select * into v_template from public.package_catalog
    where id = p_package_id and is_active for share;
    if not found then
      raise exception 'החבילה אינה קיימת או אינה פעילה.';
    end if;
    v_package_name := v_template.name;
    v_credits := coalesce(p_credits, v_template.credits);
    v_term := coalesce(p_term_months, v_template.term_months);
    v_price := coalesce(p_price_before_vat, v_template.total_price_before_vat);
    v_benefits := coalesce(p_benefits, v_template.benefits);
  else
    v_package_name := nullif(btrim(p_custom_name), '');
    v_credits := p_credits;
    v_term := p_term_months;
    v_price := p_price_before_vat;
    v_benefits := p_benefits;
  end if;

  if v_package_name is null or v_credits is null or v_credits <= 0
     or round(v_credits, 2) <> v_credits
     or v_term is null or v_term <= 0 or v_price is null or v_price <= 0
     or v_price > 99999999 or round(v_price, 2) <> v_price
     or v_benefits is null or jsonb_typeof(v_benefits) <> 'array' then
    raise exception 'פרטי החבילה או ההסכם האישי אינם תקינים.';
  end if;

  select count(*), coalesce(sum((item ->> 'amount_before_vat')::numeric), 0),
         coalesce(sum(round((item ->> 'amount_before_vat')::numeric * (1 + v_vat), 2)), 0)
  into v_count, v_sum, v_gross
  from jsonb_array_elements(p_installments) as installment(item);
  if v_count <> jsonb_array_length(p_installments)
     or abs(v_sum - v_price) > 0.01 then
    raise exception 'סכום התשלומים לפני מע"מ חייב להיות שווה למחיר החבילה.';
  end if;
  if v_gross <= 0 or v_gross > 99999999 then
    raise exception 'סכום התשלומים הכולל לאחר מע"מ חורג מהטווח המותר.';
  end if;

  v_actor_label := coalesce(
    nullif(auth.jwt() -> 'user_metadata' ->> 'full_name', ''),
    nullif(auth.jwt() -> 'user_metadata' ->> 'name', ''),
    nullif(auth.jwt() ->> 'email', ''),
    'משתמשת'
  );

  insert into public.customer_packages (
    client_id, package_id, package_name_snapshot, credits_granted,
    term_months, price_before_vat, vat_rate_snapshot, gross_total,
    starts_on, ends_on, installment_count, benefits_snapshot, notes,
    idempotency_key, created_by
  )
  values (
    p_client_id, p_package_id, v_package_name, v_credits, v_term,
    v_price, v_vat, v_gross, p_starts_on, p_ends_on,
    v_count, v_benefits, coalesce(p_notes, ''),
    p_idempotency_key, auth.uid()
  )
  returning id into v_package_id;

  insert into public.credit_ledger (
    client_id, delta, entry_type, customer_package_id, reason,
    idempotency_key, created_by
  )
  values (
    p_client_id, v_credits, 'package_grant', v_package_id,
    'הקצאת קרדיטים ברכישת ' || v_package_name,
    gen_random_uuid(), auth.uid()
  );

  for v_item in select value from jsonb_array_elements(p_installments)
  loop
    v_index := v_index + 1;
    if nullif(v_item ->> 'due_on', '') is null
       or nullif(v_item ->> 'amount_before_vat', '') is null
       or (v_item ->> 'amount_before_vat')::numeric <= 0
       or (v_item ->> 'amount_before_vat')::numeric > 99999999
       or round((v_item ->> 'amount_before_vat')::numeric, 2)
            <> (v_item ->> 'amount_before_vat')::numeric then
      raise exception 'פרטי התשלום % אינם תקינים.', v_index;
    end if;

    insert into public.package_installments (
      customer_package_id, installment_number, due_on,
      amount_before_vat, vat_rate_snapshot, amount_due
    )
    values (
      v_package_id, v_index, (v_item ->> 'due_on')::date,
      (v_item ->> 'amount_before_vat')::numeric,
      v_vat,
      round((v_item ->> 'amount_before_vat')::numeric * (1 + v_vat), 2)
    )
    returning id into v_installment_id;

    insert into public.financial_obligations (
      package_installment_id, amount_due, due_on, status, created_by
    )
    select v_installment_id, installment.amount_due,
           installment.due_on, 'pending', auth.uid()
    from public.package_installments as installment
    where installment.id = v_installment_id
    returning id into v_obligation_id;

    v_result := v_result || jsonb_build_array(jsonb_build_object(
      'installment_id', v_installment_id,
      'obligation_id', v_obligation_id,
      'due_on', v_item ->> 'due_on'
    ));
  end loop;

  for v_item in select value from jsonb_array_elements(v_benefits)
  loop
    if nullif(v_item ->> 'key', '') is null
       or nullif(v_item ->> 'label', '') is null
       or nullif(v_item ->> 'unit', '') is null
       or (v_item ->> 'quantity')::numeric <= 0 then
      raise exception 'הטבה בחבילה אינה תקינה.';
    end if;
    insert into public.package_benefit_ledger (
      customer_package_id, benefit_key, label_snapshot,
      quantity_delta, unit_snapshot, reason, idempotency_key, created_by
    )
    values (
      v_package_id, v_item ->> 'key', v_item ->> 'label',
      (v_item ->> 'quantity')::numeric, v_item ->> 'unit',
      'הקצאת הטבה בחבילת ' || v_package_name,
      gen_random_uuid(), auth.uid()
    );
  end loop;

  v_result := jsonb_build_object(
    'customer_package_id', v_package_id,
    'credits_granted', v_credits,
    'credit_balance_after', (
      select coalesce(sum(delta), 0)
      from public.credit_ledger
      where client_id = p_client_id
    ),
    'gross_total', v_gross,
    'installments', v_result
  );
  update private.business_operations
  set response = v_result where idempotency_key = p_idempotency_key;
  return v_result;
end;
$function$;

revoke all on function public.purchase_customer_package(text, uuid, text, numeric, integer, numeric, date, date, jsonb, jsonb, text, uuid)
  from public, anon;
grant execute on function public.purchase_customer_package(text, uuid, text, numeric, integer, numeric, date, date, jsonb, jsonb, text, uuid)
  to authenticated;

create or replace function public.adjust_package_benefit(
  p_customer_package_id uuid,
  p_benefit_key text,
  p_label text,
  p_quantity_delta numeric,
  p_unit text,
  p_reason text,
  p_idempotency_key uuid
)
returns numeric
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_cached jsonb;
  v_package public.customer_packages%rowtype;
  v_balance numeric(12, 2);
begin
  if auth.uid() is null or not private.is_approved_user() then
    raise exception 'החשבון אינו מורשה לבצע פעולה זו.';
  end if;
  if p_benefit_key is null or length(btrim(p_benefit_key)) = 0
     or p_label is null or length(btrim(p_label)) = 0
     or p_unit is null or length(btrim(p_unit)) = 0
     or p_quantity_delta is null or p_quantity_delta = 0
     or p_reason is null or length(btrim(p_reason)) < 3 then
    raise exception 'פרטי תנועת ההטבה אינם תקינים.';
  end if;

  v_cached := private.claim_business_operation(
    p_idempotency_key, 'adjust_package_benefit',
    pg_catalog.md5(concat_ws(':', p_customer_package_id, p_benefit_key,
      p_label, p_quantity_delta, p_unit, p_reason))
  );
  if v_cached is not null then
    return (v_cached ->> 'benefit_balance')::numeric;
  end if;

  select * into v_package from public.customer_packages
  where id = p_customer_package_id for update;
  if not found then
    raise exception 'החבילה של הלקוח לא נמצאה.';
  end if;

  select coalesce(sum(quantity_delta), 0) into v_balance
  from public.package_benefit_ledger
  where customer_package_id = p_customer_package_id
    and benefit_key = p_benefit_key;
  if v_balance + p_quantity_delta < 0 then
    raise exception 'אין די הטבות זמינות לביצוע הפעולה.';
  end if;

  insert into public.package_benefit_ledger (
    customer_package_id, benefit_key, label_snapshot,
    quantity_delta, unit_snapshot, reason, idempotency_key, created_by
  )
  values (
    p_customer_package_id, btrim(p_benefit_key), btrim(p_label),
    p_quantity_delta, btrim(p_unit), btrim(p_reason),
    p_idempotency_key, auth.uid()
  );

  v_balance := v_balance + p_quantity_delta;
  update private.business_operations
  set response = jsonb_build_object('benefit_balance', v_balance)
  where idempotency_key = p_idempotency_key;
  return v_balance;
end;
$function$;

revoke all on function public.adjust_package_benefit(uuid, text, text, numeric, text, text, uuid)
  from public, anon;
grant execute on function public.adjust_package_benefit(uuid, text, text, numeric, text, text, uuid)
  to authenticated;

create or replace function public.update_business_order(
  p_order_id text,
  p_expected_updated_at timestamptz,
  p_client_id text,
  p_publication_date date,
  p_section text,
  p_notes text,
  p_sheet_number text,
  p_legacy_amount numeric,
  p_cash_amount_before_vat numeric,
  p_credits_used numeric,
  p_product_id uuid,
  p_due_on date,
  p_update_due_on boolean,
  p_idempotency_key uuid
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_cached jsonb;
  v_order public.orders%rowtype;
  v_obligation public.financial_obligations%rowtype;
  v_product public.product_catalog%rowtype;
  v_original_client_id text;
  v_legacy_amount numeric(12, 2);
  v_cash_amount numeric(12, 2);
  v_credits numeric;
  v_gross_amount numeric(12, 2);
  v_credit_delta numeric(12, 2);
  v_updated_at timestamptz;
  v_result jsonb;
begin
  if auth.uid() is null or not private.is_approved_user() then
    raise exception 'החשבון אינו מורשה לבצע פעולה זו.';
  end if;
  if p_order_id is null or p_expected_updated_at is null
     or p_client_id is null or p_publication_date is null
     or p_section is null or length(btrim(p_section)) = 0
     or length(btrim(p_section)) > 120
     or p_notes is null or length(p_notes) > 5000
     or (p_sheet_number is not null and length(btrim(p_sheet_number)) > 80)
     or p_update_due_on is null then
    raise exception 'פרטי ההזמנה אינם תקינים.';
  end if;
  if p_legacy_amount is not null
     and (p_legacy_amount < 0 or p_legacy_amount > 99999999
       or round(p_legacy_amount, 2) <> p_legacy_amount) then
    raise exception 'הסכום הכספי אינו תקין.';
  end if;
  if p_cash_amount_before_vat is not null
     and (p_cash_amount_before_vat <= 0
       or p_cash_amount_before_vat > 99999999
       or round(p_cash_amount_before_vat, 2) <> p_cash_amount_before_vat) then
    raise exception 'המחיר לפני מע"מ אינו תקין.';
  end if;
  if p_credits_used is not null
     and (p_credits_used <= 0 or round(p_credits_used, 2) <> p_credits_used) then
    raise exception 'כמות הקרדיטים חייבת להיות חיובית ובדיוק של שתי ספרות אחרי הנקודה.';
  end if;

  v_cached := private.claim_business_operation(
    p_idempotency_key,
    'update_business_order',
    pg_catalog.md5(jsonb_build_object(
      'order_id', p_order_id,
      'expected_updated_at', p_expected_updated_at,
      'client_id', p_client_id,
      'publication_date', p_publication_date,
      'section', p_section,
      'notes', p_notes,
      'sheet_number', p_sheet_number,
      'legacy_amount', p_legacy_amount,
      'cash_amount_before_vat', p_cash_amount_before_vat,
      'credits_used', p_credits_used,
      'product_id', p_product_id,
      'due_on', p_due_on,
      'update_due_on', p_update_due_on
    )::text)
  );
  if v_cached is not null then
    return v_cached;
  end if;

  select client_id into v_original_client_id
  from public.orders
  where id = p_order_id;
  if not found then
    raise exception 'ההזמנה לא נמצאה.';
  end if;

  perform clients.id
  from public.clients as clients
  where clients.id in (v_original_client_id, p_client_id)
  order by clients.id
  for update;

  select * into v_order
  from public.orders
  where id = p_order_id
  for update;
  if not found then
    raise exception 'ההזמנה לא נמצאה.';
  end if;
  if v_order.updated_at is distinct from p_expected_updated_at then
    raise exception using
      errcode = '40001',
      message = 'ההזמנה השתנתה אצל משתמש אחר. רענני את הנתונים ונסי שוב.';
  end if;
  if v_order.client_id is distinct from v_original_client_id then
    raise exception using
      errcode = '40001',
      message = 'ההזמנה השתנתה אצל משתמש אחר. רענני את הנתונים ונסי שוב.';
  end if;
  if not exists (select 1 from public.clients where id = p_client_id) then
    raise exception 'הלקוח שנבחר אינו קיים.';
  end if;
  if p_product_id is not null then
    if v_order.billing_mode = 'legacy' then
      raise exception 'אי אפשר לשייך מוצר להזמנה היסטורית ללא המרה מפורשת.';
    end if;
    select * into v_product
    from public.product_catalog
    where id = p_product_id and is_active
    for share;
    if not found or v_product.credit_cost is null
       or v_product.base_price_before_vat is null then
      raise exception 'המוצר אינו פעיל או שחסרים לו ערכי מחיר מאומתים.';
    end if;
  end if;

  if v_order.billing_mode = 'legacy' then
    if p_cash_amount_before_vat is not null or p_credits_used is not null
       or p_product_id is not null then
      raise exception 'אי אפשר לשנות חיוב או מוצר של הזמנה היסטורית ללא המרתה המפורשת.';
    end if;
    if p_update_due_on
       and coalesce(p_legacy_amount, v_order.amount) = 0 then
      raise exception 'להזמנה היסטורית בסכום אפס אין מועד פירעון.';
    end if;
    if (p_legacy_amount is not null and p_legacy_amount <> v_order.amount)
       or p_update_due_on then
      select * into v_obligation
      from public.financial_obligations
      where order_id = v_order.id
      for update;
      if not found then
        if v_order.amount <> 0 or p_legacy_amount is null
           or p_legacy_amount <= 0 then
          raise exception 'חסר חיוב להזמנה ההיסטורית; נדרשת בדיקת נתונים לפני עריכה.';
        end if;
        if exists (select 1 from public.payments where order_id = v_order.id) then
          raise exception 'נמצאה היסטוריית תשלום להזמנת legacy בסכום אפס; נדרשת התאמה ידנית לפני שינוי.';
        end if;
        insert into public.financial_obligations (
          order_id, amount_due, due_on, status, legacy_snapshot, created_by
        )
        values (
          v_order.id, p_legacy_amount,
          case when p_update_due_on then p_due_on else null end,
          'pending', true, auth.uid()
        );
      else
        if p_legacy_amount is not null
           and p_legacy_amount <> v_order.amount
           and v_obligation.status <> 'pending' then
          raise exception 'אי אפשר לשנות סכום של הזמנה שסומנה כשולמה.';
        end if;
        if p_legacy_amount is not null and p_legacy_amount <> v_order.amount then
          if exists (select 1 from public.payments where order_id = v_order.id)
             or exists (
               select 1
               from public.business_payment_events as events
               where events.obligation_id = v_obligation.id
             ) then
            raise exception 'אי אפשר לשנות סכום לאחר שנרשמה היסטוריית תשלום; יש לבצע פעולת התאמה מתועדת.';
          end if;
          if p_legacy_amount = 0 then
            delete from public.financial_obligations
            where id = v_obligation.id;
          else
            update public.financial_obligations
            set amount_due = p_legacy_amount
            where id = v_obligation.id;
          end if;
        end if;
        if p_update_due_on and p_legacy_amount is distinct from 0 then
          update public.financial_obligations
          set due_on = p_due_on
          where id = v_obligation.id;
        end if;
      end if;
    end if;
  elsif v_order.billing_mode = 'cash' then
    if p_legacy_amount is not null or p_credits_used is not null then
      raise exception 'סוג החיוב של הזמנה קיימת אינו ניתן להחלפה בעריכה רגילה.';
    end if;
    if p_cash_amount_before_vat is not null or p_product_id is not null
       or p_update_due_on then
      select * into v_obligation
      from public.financial_obligations
      where order_id = v_order.id
      for update;
      if not found then
        raise exception 'חסר חיוב להזמנה; נדרשת בדיקת נתונים לפני עריכה.';
      end if;
      if v_obligation.status <> 'pending'
         and (p_cash_amount_before_vat is not null or p_product_id is not null) then
        raise exception 'אי אפשר לשנות מחיר או מוצר של הזמנה שסומנה כשולמה.';
      end if;
      if (p_cash_amount_before_vat is not null or p_product_id is not null)
         and (
           exists (select 1 from public.payments where order_id = v_order.id)
           or exists (
             select 1 from public.business_payment_events as events
             where events.obligation_id = v_obligation.id
           )
         ) then
        raise exception 'אי אפשר לשנות מחיר או מוצר לאחר שנרשמה היסטוריית תשלום.';
      end if;
      if p_cash_amount_before_vat is not null then
        if v_order.vat_rate_snapshot is null then
          raise exception 'חסר צילום שיעור מע"מ להזמנה.';
        end if;
        v_cash_amount := p_cash_amount_before_vat;
        v_gross_amount := round(v_cash_amount * (1 + v_order.vat_rate_snapshot), 2);
        if v_gross_amount <= 0 or v_gross_amount > 99999999 then
          raise exception 'הסכום הכולל לאחר מע"מ אינו תקין.';
        end if;
        update public.financial_obligations
        set amount_due = v_gross_amount
        where id = v_obligation.id;
      end if;
      if p_update_due_on then
        update public.financial_obligations
        set due_on = p_due_on
        where id = v_obligation.id;
      end if;
    end if;
  elsif v_order.billing_mode = 'credits' then
    if p_legacy_amount is not null or p_cash_amount_before_vat is not null
       or p_update_due_on then
      raise exception 'הזמנת קרדיטים אינה כוללת חיוב כספי או מועד פירעון.';
    end if;
    v_credits := coalesce(p_credits_used, v_order.credits_used);
    if v_credits is null or v_credits <= 0 or round(v_credits, 2) <> v_credits then
      raise exception 'כמות הקרדיטים בהזמנה אינה תקינה.';
    end if;

    if v_order.client_id <> p_client_id
       or v_credits <> v_order.credits_used then
      if v_order.client_id = p_client_id then
        v_credit_delta := v_order.credits_used - v_credits;
        if v_credit_delta <> 0 then
          insert into public.credit_ledger (
            client_id, delta, entry_type, order_id, reason,
            idempotency_key, created_by
          )
          values (
            p_client_id, v_credit_delta, 'correction', v_order.id,
            'תיקון ניצול קרדיטים בעקבות עריכת הזמנה ' || v_order.order_number,
            gen_random_uuid(), auth.uid()
          );
        end if;
      else
        if v_order.credits_used <> 0 then
          insert into public.credit_ledger (
            client_id, delta, entry_type, order_id, reason,
            idempotency_key, created_by
          )
          values (
            v_order.client_id, v_order.credits_used, 'correction', v_order.id,
            'העברת שיוך לקוח בהזמנה ' || v_order.order_number,
            gen_random_uuid(), auth.uid()
          );
        end if;
        if v_credits <> 0 then
          insert into public.credit_ledger (
            client_id, delta, entry_type, order_id, reason,
            idempotency_key, created_by
          )
          values (
            p_client_id, -v_credits, 'correction', v_order.id,
            'העברת שיוך לקוח בהזמנה ' || v_order.order_number,
            gen_random_uuid(), auth.uid()
          );
        end if;
      end if;
    end if;
  else
    raise exception 'סוג החיוב של ההזמנה אינו מוכר.';
  end if;

  update public.orders
  set client_id = p_client_id,
      publication_date = p_publication_date,
      section = btrim(p_section),
      notes = p_notes,
      sheet_number = nullif(btrim(coalesce(p_sheet_number, '')), ''),
      payment_status = case
        when v_order.billing_mode = 'legacy'
             and v_order.amount = 0
             and p_legacy_amount > 0 then 'pending'
        else payment_status
      end,
      amount = case
        when v_order.billing_mode = 'legacy' and p_legacy_amount is not null
          then p_legacy_amount
        when v_order.billing_mode = 'cash' and p_cash_amount_before_vat is not null
          then v_gross_amount
        else amount
      end,
      cash_amount_before_vat = case
        when v_order.billing_mode = 'cash' and p_cash_amount_before_vat is not null
          then p_cash_amount_before_vat
        else cash_amount_before_vat
      end,
      credits_used = case
        when v_order.billing_mode = 'credits' then v_credits
        else credits_used
      end,
      product_id = case when p_product_id is not null then p_product_id else product_id end,
      product_name_snapshot = case
        when p_product_id is not null then v_product.name
        else product_name_snapshot
      end,
      product_dimensions_snapshot = case
        when p_product_id is not null then v_product.dimensions
        else product_dimensions_snapshot
      end,
      product_price_snapshot = case
        when p_product_id is not null then v_product.base_price_before_vat
        else product_price_snapshot
      end,
      product_credit_cost_snapshot = case
        when p_product_id is not null then v_product.credit_cost
        else product_credit_cost_snapshot
      end
  where id = v_order.id
  returning updated_at into v_updated_at;

  v_result := jsonb_build_object(
    'id', v_order.id,
    'updated_at', v_updated_at,
    'billing_mode', v_order.billing_mode,
    'amount', case
      when v_order.billing_mode = 'legacy' then coalesce(p_legacy_amount, v_order.amount)
      when v_order.billing_mode = 'cash' then coalesce(v_gross_amount, v_order.amount)
      else 0
    end,
    'credits_used', case
      when v_order.billing_mode = 'credits' then v_credits
      else null
    end
  );
  update private.business_operations
  set response = v_result
  where idempotency_key = p_idempotency_key;
  return v_result;
end;
$function$;

revoke all on function public.update_business_order(
  text, timestamptz, text, date, text, text, text, numeric, numeric,
  numeric, uuid, date, boolean, uuid
) from public, anon;
grant execute on function public.update_business_order(
  text, timestamptz, text, date, text, text, text, numeric, numeric,
  numeric, uuid, date, boolean, uuid
) to authenticated;

create or replace function public.delete_business_order(
  p_order_id text,
  p_expected_updated_at timestamptz,
  p_reason text,
  p_idempotency_key uuid
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_cached jsonb;
  v_order public.orders%rowtype;
  v_obligation_id uuid;
  v_result jsonb;
begin
  if auth.uid() is null or not private.is_approved_user() then
    raise exception 'החשבון אינו מורשה לבצע פעולה זו.';
  end if;
  if p_order_id is null or p_expected_updated_at is null
     or p_reason is null or length(btrim(p_reason)) < 3 then
    raise exception 'נדרש מזהה גרסה והסבר למחיקת הזמנה.';
  end if;

  v_cached := private.claim_business_operation(
    p_idempotency_key,
    'delete_business_order',
    pg_catalog.md5(jsonb_build_object(
      'order_id', p_order_id,
      'expected_updated_at', p_expected_updated_at,
      'reason', p_reason
    )::text)
  );
  if v_cached is not null then
    return v_cached;
  end if;

  select * into v_order
  from public.orders
  where id = p_order_id
  for update;
  if not found then
    raise exception 'ההזמנה לא נמצאה.';
  end if;
  if v_order.updated_at is distinct from p_expected_updated_at then
    raise exception using
      errcode = '40001',
      message = 'ההזמנה השתנתה אצל משתמש אחר. רענני את הנתונים ונסי שוב.';
  end if;
  if v_order.billing_mode <> 'legacy' or v_order.payment_status <> 'pending' then
    raise exception 'אפשר למחוק רק הזמנה היסטורית שלא סומנה כשולמה; הזמנות עסקיות נשמרות לצורכי תיעוד.';
  end if;
  if exists (select 1 from public.payments where order_id = v_order.id)
     or exists (select 1 from public.business_payment_events as events
       join public.financial_obligations as obligations
         on obligations.id = events.obligation_id
       where obligations.order_id = v_order.id)
     or exists (select 1 from public.credit_ledger where order_id = v_order.id)
     or exists (select 1 from public.credit_cash_conversions where order_id = v_order.id) then
    raise exception 'להזמנה יש היסטוריית תשלומים או קרדיטים; לא ניתן למחוק אותה.';
  end if;

  select id into v_obligation_id
  from public.financial_obligations
  where order_id = v_order.id
  for update;
  if not found then
    raise exception 'חסר חיוב להזמנה; נדרשת בדיקת נתונים לפני מחיקה.';
  end if;

  delete from public.financial_obligations where id = v_obligation_id;
  delete from public.orders where id = v_order.id;

  v_result := jsonb_build_object('id', v_order.id, 'deleted', true);
  update private.business_operations
  set response = v_result
  where idempotency_key = p_idempotency_key;
  return v_result;
end;
$function$;

revoke all on function public.delete_business_order(text, timestamptz, text, uuid)
  from public, anon;
grant execute on function public.delete_business_order(text, timestamptz, text, uuid)
  to authenticated;

create or replace function public.set_obligation_paid(
  p_obligation_id uuid,
  p_is_paid boolean,
  p_reason text,
  p_expected_updated_at timestamptz,
  p_idempotency_key uuid
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_cached jsonb;
  v_obligation public.financial_obligations%rowtype;
  v_order_id text;
  v_order_updated_at timestamptz;
  v_event_type text;
  v_event_amount numeric(12, 2);
  v_recorded_payments numeric(12, 2);
  v_recorded_business_events numeric(12, 2);
  v_recorded_total numeric(12, 2);
  v_result jsonb;
begin
  if auth.uid() is null or not private.is_approved_user() then
    raise exception 'החשבון אינו מורשה לבצע פעולה זו.';
  end if;
  if p_is_paid is null then
    raise exception 'יש לבחור סטטוס תשלום.';
  end if;
  if p_expected_updated_at is null then
    raise exception 'חסר מזהה הגרסה של החיוב. יש לרענן את הנתונים.';
  end if;
  if not p_is_paid and (p_reason is null or length(btrim(p_reason)) < 3) then
    raise exception 'נדרש הסבר קצר לפתיחה מחדש של תשלום שסומן כשולם.';
  end if;

  v_cached := private.claim_business_operation(
    p_idempotency_key, 'set_obligation_paid',
    pg_catalog.md5(concat_ws(':', p_obligation_id, p_is_paid, p_reason, p_expected_updated_at))
  );
  if v_cached is not null then
    return v_cached;
  end if;

  select order_id into v_order_id
  from public.financial_obligations
  where id = p_obligation_id;
  if not found then
    raise exception 'החיוב לא נמצא.';
  end if;

  if v_order_id is not null then
    select updated_at into v_order_updated_at
    from public.orders
    where id = v_order_id
    for update;
    if not found then
      raise exception 'ההזמנה המשויכת לחיוב אינה קיימת.';
    end if;
    if v_order_updated_at is distinct from p_expected_updated_at then
      raise exception using
        errcode = '40001',
        message = 'ההזמנה השתנתה אצל משתמש אחר. רענני את הנתונים ונסי שוב.';
    end if;
  end if;

  select * into v_obligation from public.financial_obligations
  where id = p_obligation_id for update;
  if not found then
    raise exception 'החיוב אינו קיים עוד.';
  end if;
  if v_obligation.order_id is null
     and v_obligation.updated_at is distinct from p_expected_updated_at then
    raise exception using
      errcode = '40001',
      message = 'החיוב השתנה אצל משתמש אחר. רענני את הנתונים ונסי שוב.';
  end if;

  select coalesce(sum(payments.amount), 0) into v_recorded_payments
  from public.payments as payments
  where payments.order_id = v_obligation.order_id;
  select coalesce(sum(events.amount), 0) into v_recorded_business_events
  from public.business_payment_events as events
  where events.obligation_id = p_obligation_id;
  v_recorded_total := v_recorded_payments + v_recorded_business_events;

  if (v_obligation.status = 'paid') = p_is_paid then
    v_result := jsonb_build_object(
      'obligation_id', p_obligation_id,
      'status', v_obligation.status,
      'changed', false
    );
  else
    if p_is_paid then
      if v_recorded_total < 0 or v_recorded_total > v_obligation.amount_due then
        raise exception 'תנועות התשלום הקיימות אינן תואמות לסכום החיוב. נדרשת התאמה ידנית לפני עדכון.';
      end if;
      if v_recorded_total > 0 and v_recorded_total < v_obligation.amount_due then
        raise exception 'נמצאו תשלומים קודמים חלקיים. מנגנון זה אינו תומך בתשלומים חלקיים; נדרשת התאמה ידנית.';
      end if;
      update public.financial_obligations
      set status = 'paid', legacy_snapshot = false,
          paid_at = pg_catalog.now(), paid_by = auth.uid()
      where id = p_obligation_id;
      if v_recorded_total = 0 then
        v_event_type := 'payment';
        v_event_amount := v_obligation.amount_due;
      else
        v_event_type := null;
      end if;
    else
      if v_recorded_total < 0 or v_recorded_total > v_obligation.amount_due then
        raise exception 'תנועות התשלום הקיימות אינן תואמות לסכום החיוב. נדרשת התאמה ידנית לפני עדכון.';
      end if;
      update public.financial_obligations
      set status = 'pending', legacy_snapshot = false,
          paid_at = null, paid_by = null
      where id = p_obligation_id;
      if v_recorded_total > 0 then
        if v_recorded_total <> v_obligation.amount_due then
          raise exception 'נמצאו תשלומים חלקיים. נדרשת התאמה ידנית לפני פתיחת החיוב מחדש.';
        end if;
        v_event_type := 'reversal';
        v_event_amount := -v_recorded_total;
      elsif v_obligation.legacy_snapshot and v_obligation.status = 'paid' then
        v_event_type := 'status_correction';
        v_event_amount := 0;
      else
        raise exception 'חסר אירוע תשלום לחיוב שסומן כשולם. נדרשת בדיקת היסטוריה לפני שינוי הסטטוס.';
      end if;
    end if;

    if v_event_type is not null then
      insert into public.business_payment_events (
        obligation_id, event_type, amount, notes, idempotency_key, created_by
      )
      values (
        p_obligation_id, v_event_type, v_event_amount,
        coalesce(nullif(btrim(p_reason), ''), 'עדכון סטטוס תשלום'),
        p_idempotency_key, auth.uid()
      );
    end if;

    v_result := jsonb_build_object(
      'obligation_id', p_obligation_id,
      'status', case when p_is_paid then 'paid' else 'pending' end,
      'changed', true
    );
  end if;

  if v_obligation.order_id is not null then
    update public.orders
    set payment_status = case when p_is_paid then 'paid' else 'pending' end
    where id = v_obligation.order_id
      and payment_status is distinct from case when p_is_paid then 'paid' else 'pending' end
    returning updated_at into v_order_updated_at;
    if not found then
      select updated_at into v_order_updated_at
      from public.orders
      where id = v_obligation.order_id;
    end if;
  else
    select updated_at into v_order_updated_at
    from public.financial_obligations
    where id = p_obligation_id;
  end if;
  v_result := v_result || jsonb_build_object('updated_at', v_order_updated_at);

  update private.business_operations
  set response = v_result where idempotency_key = p_idempotency_key;
  return v_result;
end;
$function$;

revoke all on function public.set_obligation_paid(uuid, boolean, text, timestamptz, uuid)
  from public, anon;
grant execute on function public.set_obligation_paid(uuid, boolean, text, timestamptz, uuid)
  to authenticated;

create or replace function public.adjust_client_credits(
  p_client_id text,
  p_delta numeric,
  p_reason text,
  p_idempotency_key uuid
)
returns numeric
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_cached jsonb;
  v_client public.clients%rowtype;
  v_balance numeric;
begin
  if auth.uid() is null or not private.is_approved_user() then
    raise exception 'החשבון אינו מורשה לבצע פעולה זו.';
  end if;
  if p_delta is null or p_delta = 0 or round(p_delta, 2) <> p_delta or p_reason is null
     or length(btrim(p_reason)) < 3 then
    raise exception 'תנועת תיקון קרדיטים מחייבת כמות שאינה אפס והסבר.';
  end if;

  v_cached := private.claim_business_operation(
    p_idempotency_key, 'adjust_client_credits',
    pg_catalog.md5(concat_ws(':', p_client_id, p_delta, p_reason))
  );
  if v_cached is not null then
    return (v_cached ->> 'credit_balance')::numeric;
  end if;

  select * into v_client from public.clients
  where id = p_client_id for update;
  if not found then
    raise exception 'הלקוח לא נמצא.';
  end if;

  insert into public.credit_ledger (
    client_id, delta, entry_type, reason, idempotency_key, created_by
  )
  values (p_client_id, p_delta, 'correction', btrim(p_reason), p_idempotency_key, auth.uid());

  select coalesce(sum(delta), 0) into v_balance
  from public.credit_ledger where client_id = p_client_id;
  update private.business_operations
  set response = jsonb_build_object('credit_balance', v_balance)
  where idempotency_key = p_idempotency_key;
  return v_balance;
end;
$function$;

revoke all on function public.adjust_client_credits(text, numeric, text, uuid) from public, anon;
grant execute on function public.adjust_client_credits(text, numeric, text, uuid) to authenticated;

create or replace function public.convert_credit_orders_to_cash(
  p_items jsonb,
  p_reason text,
  p_idempotency_key uuid
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_cached jsonb;
  v_item jsonb;
  v_order public.orders%rowtype;
  v_vat numeric(5, 4);
  v_cash numeric;
  v_gross numeric(12, 2);
  v_due_on date;
  v_obligation uuid;
  v_result jsonb := '[]'::jsonb;
  v_count integer := 0;
begin
  if auth.uid() is null or not private.is_approved_user() then
    raise exception 'החשבון אינו מורשה לבצע פעולה זו.';
  end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array'
     or jsonb_array_length(p_items) = 0
     or jsonb_array_length(p_items) > 250
     or p_reason is null or length(btrim(p_reason)) < 3 then
    raise exception 'נדרשות הזמנות והסבר תקין להמרה.';
  end if;

  v_cached := private.claim_business_operation(
    p_idempotency_key, 'convert_credit_orders_to_cash',
    pg_catalog.md5(p_items::text || ':' || p_reason)
  );
  if v_cached is not null then
    return v_cached;
  end if;

  if (
    select count(*) <> count(distinct item ->> 'order_id')
    from jsonb_array_elements(p_items) as source(item)
  ) then
    raise exception 'הבקשה מכילה הזמנה כפולה.';
  end if;

  perform clients.id
  from public.clients as clients
  where clients.id in (
    select orders.client_id
    from public.orders as orders
    join jsonb_array_elements(p_items) as source(item)
      on orders.id = source.item ->> 'order_id'
  )
  order by clients.id
  for update;

  select vat_rate into v_vat from public.business_settings where singleton;
  if v_vat is null then
    raise exception 'הגדרת המע"מ חסרה.';
  end if;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    v_count := v_count + 1;
    select * into v_order from public.orders
    where id = v_item ->> 'order_id'
    for update;
    if not found or v_order.billing_mode <> 'credits'
       or v_order.credits_used is null or v_order.credits_used <= 0 then
      raise exception 'הזמנה % אינה הזמנת קרדיטים שניתנת להמרה.', v_count;
    end if;
    v_cash := nullif(v_item ->> 'cash_amount_before_vat', '')::numeric;
    if v_cash is null or v_cash <= 0 or v_cash > 99999999
       or round(v_cash, 2) <> v_cash then
      raise exception 'לכל הזמנה יש להזין מחיר שאושר בפועל; לא חושב מחיר המרה אוטומטי.';
    end if;
    v_due_on := nullif(v_item ->> 'due_on', '')::date;
    v_gross := round(v_cash * (1 + v_vat), 2);
    if v_gross <= 0 or v_gross > 99999999 then
      raise exception 'סכום ההמרה לאחר מע"מ חורג מהטווח המותר.';
    end if;

    insert into public.credit_cash_conversions (
      order_id, original_credits, approved_price_before_vat,
      vat_rate_snapshot, gross_amount, due_on, reason,
      idempotency_key, converted_by
    )
    values (
      v_order.id, v_order.credits_used, v_cash,
      v_vat, v_gross, v_due_on, btrim(p_reason),
      p_idempotency_key, auth.uid()
    );

    insert into public.credit_ledger (
      client_id, delta, entry_type, reason, idempotency_key, created_by
    )
    values (
      v_order.client_id, v_order.credits_used, 'conversion_reversal',
      'החזרת קרדיטים בהמרת הזמנה ' || v_order.order_number || ': ' || btrim(p_reason),
      gen_random_uuid(), auth.uid()
    );

    update public.orders
    set billing_mode = 'cash',
        cash_amount_before_vat = v_cash,
        credits_used = null,
        vat_rate_snapshot = v_vat,
        amount = v_gross,
        payment_status = 'pending'
    where id = v_order.id;

    insert into public.financial_obligations (
      order_id, amount_due, due_on, status, created_by
    )
    values (v_order.id, v_gross, v_due_on, 'pending', auth.uid())
    returning id into v_obligation;

    v_result := v_result || jsonb_build_array(jsonb_build_object(
      'order_id', v_order.id, 'order_number', v_order.order_number,
      'credits_returned', v_order.credits_used,
      'gross_amount', v_gross, 'obligation_id', v_obligation
    ));
  end loop;

  update private.business_operations
  set response = v_result where idempotency_key = p_idempotency_key;
  return v_result;
end;
$function$;

revoke all on function public.convert_credit_orders_to_cash(jsonb, text, uuid)
  from public, anon;
grant execute on function public.convert_credit_orders_to_cash(jsonb, text, uuid)
  to authenticated;

-- Read access for approved users only; all writes to new ledgers/obligations
-- are performed by the security-definer RPCs above.
do $policies$
declare
  v_table text;
  v_column text;
begin
  foreach v_table in array array[
    'business_settings', 'product_catalog', 'package_catalog',
    'customer_packages', 'package_installments', 'financial_obligations',
    'business_payment_events', 'credit_ledger', 'package_benefit_ledger',
    'credit_cash_conversions', 'business_audit_log'
  ]
  loop
    execute pg_catalog.format(
      'alter table public.%I enable row level security', v_table
    );
    execute pg_catalog.format(
      'alter table public.%I force row level security', v_table
    );
    execute pg_catalog.format(
      'revoke all on table public.%I from public, anon, authenticated', v_table
    );
    for v_column in
      select attribute.attname
      from pg_catalog.pg_attribute as attribute
      where attribute.attrelid =
        pg_catalog.to_regclass('public.' || v_table)
        and attribute.attnum > 0
        and not attribute.attisdropped
    loop
      execute pg_catalog.format(
        'revoke insert (%I) on table public.%I from public, anon, authenticated',
        v_column, v_table
      );
      execute pg_catalog.format(
        'revoke update (%I) on table public.%I from public, anon, authenticated',
        v_column, v_table
      );
      execute pg_catalog.format(
        'revoke references (%I) on table public.%I from public, anon, authenticated',
        v_column, v_table
      );
    end loop;
    execute pg_catalog.format(
      'grant select on table public.%I to authenticated', v_table
    );
    execute pg_catalog.format(
      'drop policy if exists %I on public.%I',
      'approved_read_' || v_table, v_table
    );
    execute pg_catalog.format(
      'create policy %I on public.%I for select to authenticated using ((select private.is_approved_user()))',
      'approved_read_' || v_table, v_table
    );
  end loop;
end;
$policies$;

-- Keep reads behind the existing approved-user policies. Direct order and
-- payment writes remain temporarily available for the phase-1 compatibility
-- window; the separate cutover script revokes them after the new UI is ready.
alter table public.clients enable row level security;
alter table public.clients force row level security;
alter table public.orders enable row level security;
alter table public.orders force row level security;
alter table public.payments enable row level security;
alter table public.payments force row level security;

revoke all on table public.clients from public, anon, authenticated;
grant select on table public.clients, public.orders, public.payments
  to authenticated;
grant insert (id, name, phone, email) on table public.clients to authenticated;
grant update (name, phone, email, internal_notes)
  on table public.clients to authenticated;

drop policy if exists "approved users only clients" on public.clients;
create policy "approved users only clients"
  on public.clients as restrictive
  for all to authenticated
  using ((select private.is_approved_user()))
  with check ((select private.is_approved_user()));

drop policy if exists "approved users only orders" on public.orders;
create policy "approved users only orders"
  on public.orders as restrictive
  for all to authenticated
  using ((select private.is_approved_user()))
  with check ((select private.is_approved_user()));

drop policy if exists "approved users only payments" on public.payments;
create policy "approved users only payments"
  on public.payments as restrictive
  for all to authenticated
  using ((select private.is_approved_user()))
  with check ((select private.is_approved_user()));

-- Shared audit history for legacy CRUD as well as future RPCs.
drop trigger if exists clients_business_audit on public.clients;
create trigger clients_business_audit
  after insert or update or delete on public.clients
  for each row execute function private.write_business_audit();

drop trigger if exists orders_business_audit on public.orders;
create trigger orders_business_audit
  after insert or update or delete on public.orders
  for each row execute function private.write_business_audit();

create or replace view public.business_order_financial_summary
with (security_invoker = true)
as
select
  orders.id as order_id,
  orders.client_id,
  orders.order_number,
  orders.publication_date,
  orders.section,
  orders.sheet_number,
  orders.billing_mode,
  case when orders.billing_mode = 'credits' then 0::numeric
       else coalesce(obligations.amount_due, orders.amount)::numeric end as cash_due,
  case
    when orders.billing_mode = 'legacy' and orders.amount = 0 then 0::numeric
    when orders.billing_mode = 'credits' then 0::numeric
    when payments.payment_count + events.event_count = 0
      and obligations.legacy_snapshot
      and obligations.status = 'paid'
      then obligations.amount_due
    else payments.received + events.received
  end as cash_received,
  coalesce(obligations.due_on, null::date) as due_on,
  coalesce(obligations.status, orders.payment_status) as payment_status,
  coalesce(obligations.legacy_snapshot, orders.billing_mode = 'legacy') as legacy_snapshot,
  case
    when orders.billing_mode = 'legacy' and orders.amount = 0 then 'non_cash_order'
    when payments.payment_count > 0 and events.event_count > 0 then 'combined_records'
    when payments.payment_count > 0 then 'public_payments'
    when events.event_count > 0 then 'business_payment_events'
    when obligations.legacy_snapshot and obligations.status = 'paid'
      then 'legacy_paid_status_without_receipt_date'
    else 'no_receipt_record'
  end as receipt_basis,
  payments.payment_count > 0 or events.event_count > 0 as has_payment_history,
  obligations.id is null
    and orders.billing_mode <> 'credits'
    and not (orders.billing_mode = 'legacy' and orders.amount = 0)
    as missing_obligation,
  (
    (coalesce(obligations.status, orders.payment_status) = 'paid'
      and case when orders.billing_mode = 'credits' then 0::numeric
               else coalesce(obligations.amount_due, orders.amount)::numeric end >
          case
            when orders.billing_mode = 'credits' then 0::numeric
            when payments.payment_count + events.event_count = 0
              and obligations.legacy_snapshot and obligations.status = 'paid'
              then obligations.amount_due
            else payments.received + events.received
          end)
    or
    (coalesce(obligations.status, orders.payment_status) = 'pending'
      and case when orders.billing_mode = 'credits' then 0::numeric
               else coalesce(obligations.amount_due, orders.amount)::numeric end > 0
      and case
            when orders.billing_mode = 'credits' then 0::numeric
            when payments.payment_count + events.event_count = 0
              and obligations.legacy_snapshot and obligations.status = 'paid'
              then obligations.amount_due
            else payments.received + events.received
          end >= coalesce(obligations.amount_due, orders.amount))
  ) as payment_status_mismatch
from public.orders as orders
left join public.financial_obligations as obligations
  on obligations.order_id = orders.id
left join lateral (
  select coalesce(sum(payments.amount), 0)::numeric(12, 2) as received,
         count(*)::integer as payment_count
  from public.payments as payments
  where payments.order_id = orders.id
) as payments on true
left join lateral (
  select coalesce(sum(events.amount), 0)::numeric(12, 2) as received,
         count(*)::integer as event_count
  from public.business_payment_events as events
  where events.obligation_id = obligations.id
) as events on true;

create or replace view public.business_financial_summary
with (security_invoker = true)
as
select
  'order'::text as item_type,
  orders.order_id as item_id,
  orders.client_id,
  orders.order_number,
  orders.sheet_number,
  orders.section as description,
  orders.publication_date as item_date,
  orders.billing_mode,
  orders.cash_due,
  orders.cash_received,
  greatest(orders.cash_due - orders.cash_received, 0)::numeric(12, 2) as cash_outstanding,
  orders.due_on,
  orders.payment_status,
  case when greatest(orders.cash_due - orders.cash_received, 0) > 0
            and orders.due_on < current_date
       then greatest(orders.cash_due - orders.cash_received, 0)
       else 0::numeric end::numeric(12, 2) as overdue_amount,
  case when greatest(orders.cash_due - orders.cash_received, 0) > 0
            and orders.due_on > current_date
       then greatest(orders.cash_due - orders.cash_received, 0)
       else 0::numeric end::numeric(12, 2) as future_amount,
  case when greatest(orders.cash_due - orders.cash_received, 0) > 0
            and orders.due_on = current_date
       then greatest(orders.cash_due - orders.cash_received, 0)
       else 0::numeric end::numeric(12, 2) as due_today_amount,
  case when greatest(orders.cash_due - orders.cash_received, 0) > 0
            and orders.due_on is null
       then greatest(orders.cash_due - orders.cash_received, 0)
       else 0::numeric end::numeric(12, 2) as no_due_date_amount,
  orders.legacy_snapshot,
  orders.receipt_basis,
  orders.has_payment_history,
  orders.missing_obligation,
  orders.payment_status_mismatch
from public.business_order_financial_summary as orders
union all
select
  'package_installment'::text,
  installments.id::text,
  packages.client_id,
  null::bigint,
  null::text,
  packages.package_name_snapshot || ' - תשלום ' || installments.installment_number::text,
  installments.due_on,
  'package'::text,
  obligations.amount_due,
  events.received,
  greatest(obligations.amount_due - events.received, 0)::numeric(12, 2),
  obligations.due_on,
  obligations.status,
  case when greatest(obligations.amount_due - events.received, 0) > 0
            and obligations.due_on < current_date
       then greatest(obligations.amount_due - events.received, 0)
       else 0::numeric end::numeric(12, 2),
  case when greatest(obligations.amount_due - events.received, 0) > 0
            and obligations.due_on > current_date
       then greatest(obligations.amount_due - events.received, 0)
       else 0::numeric end::numeric(12, 2),
  case when greatest(obligations.amount_due - events.received, 0) > 0
            and obligations.due_on = current_date
       then greatest(obligations.amount_due - events.received, 0)
       else 0::numeric end::numeric(12, 2),
  0::numeric(12, 2),
  false,
  case when events.event_count > 0 then 'business_payment_events' else 'no_receipt_record' end,
  events.event_count > 0,
  false,
  false
from public.package_installments as installments
join public.customer_packages as packages
  on packages.id = installments.customer_package_id
join public.financial_obligations as obligations
  on obligations.package_installment_id = installments.id
left join lateral (
  select coalesce(sum(events.amount), 0)::numeric(12, 2) as received,
         count(*)::integer as event_count
  from public.business_payment_events as events
  where events.obligation_id = obligations.id
) as events on true;

create or replace view public.business_financial_totals
with (security_invoker = true)
as
select
  count(*) filter (where item_type = 'order')::bigint as order_count,
  count(*) filter (where item_type = 'package_installment')::bigint as installment_count,
  coalesce(sum(cash_due), 0)::numeric(14, 2) as total_cash_billed,
  coalesce(sum(cash_received), 0)::numeric(14, 2) as total_cash_received,
  coalesce(sum(cash_outstanding), 0)::numeric(14, 2) as total_cash_outstanding,
  coalesce(sum(overdue_amount), 0)::numeric(14, 2) as total_overdue,
  coalesce(sum(future_amount), 0)::numeric(14, 2) as total_future,
  coalesce(sum(due_today_amount), 0)::numeric(14, 2) as total_due_today,
  coalesce(sum(no_due_date_amount), 0)::numeric(14, 2) as total_without_due_date,
  count(*) filter (where legacy_snapshot)::bigint as legacy_order_count,
  count(*) filter (where missing_obligation)::bigint as orders_missing_obligation,
  count(*) filter (where payment_status_mismatch)::bigint as payment_status_mismatches
from public.business_financial_summary;

create or replace view public.business_client_credit_balances
with (security_invoker = true)
as
select clients.id as client_id,
       coalesce(sum(ledger.delta), 0)::numeric as credit_balance
from public.clients as clients
left join public.credit_ledger as ledger
  on ledger.client_id = clients.id
group by clients.id;

grant select on public.business_order_financial_summary,
  public.business_financial_summary, public.business_financial_totals,
  public.business_client_credit_balances to authenticated;
revoke all on public.business_order_financial_summary,
  public.business_financial_summary, public.business_financial_totals,
  public.business_client_credit_balances from public, anon;

-- Make all new table changes visible through Supabase Realtime.
do $realtime$
declare
  v_table text;
begin
  if not exists (
    select 1 from pg_catalog.pg_publication
    where pubname = 'supabase_realtime'
  ) then
    raise exception 'Supabase Realtime publication is unavailable; enable it before running this migration.';
  end if;

  foreach v_table in array array[
    'clients', 'orders', 'business_settings', 'product_catalog',
    'package_catalog', 'customer_packages', 'package_installments',
    'financial_obligations', 'business_payment_events', 'credit_ledger',
    'package_benefit_ledger', 'credit_cash_conversions', 'business_audit_log'
  ]
  loop
    if not exists (
      select 1 from pg_catalog.pg_publication_tables
      where pubname = 'supabase_realtime'
        and schemaname = 'public'
        and tablename = v_table
    ) then
      execute pg_catalog.format(
        'alter publication supabase_realtime add table public.%I', v_table
      );
    end if;
  end loop;
end;
$realtime$;

comment on table public.product_catalog is
  'Editable advertising product catalog. Prices/credit costs must be copied from verified business price sources.';
comment on table public.credit_ledger is
  'Append-only credit balance ledger. Negative balances are allowed; corrections are new entries.';
comment on table public.financial_obligations is
  'One obligation per cash order or package installment. Unpaid obligations without due dates are not classified as overdue.';
comment on table public.business_payment_events is
  'Append-only manual payment/reversal history. No partial payments.';
comment on table public.business_audit_log is
  'Append-only audit records for meaningful client, order, package, catalog, credit, and payment changes.';

commit;


-- =====================================================================================================
-- supabase-sheets-and-order-numbers.sql
-- =====================================================================================================
-- Sheets (גיליונות) status + business order-number range. REQUIRES APPROVAL. Run after supabase-business-upgrade.sql.
-- 1. Order numbers: new orders continue from the highest existing order_number, and never below 22000.
--    Existing order_number values and all technical IDs/relations are left unchanged.
-- 2. public.sheets: open/closed status per sheet number. Closing a sheet does NOT delete orders and does
--    NOT change any payment status: "closed" (editorial) and "paid" (financial) are independent.
--    A sheet with no row in this table is considered open. Rows are written only by set_sheet_status().
-- Safe to run twice.

begin;

do $preflight$
begin
  if pg_catalog.to_regclass('public.credit_ledger') is null
     or pg_catalog.to_regclass('private.order_number_counters') is null then
    raise exception 'Run supabase-business-upgrade.sql first.';
  end if;
end
$preflight$;

-- 1. Order-number range (counter only; no existing row is renumbered)
update private.order_number_counters
set last_number = greatest(
  last_number,
  (select coalesce(max(order_number), 0) from public.orders),
  21999
)
where counter_name = 'orders';

-- 2. Sheet status
create table if not exists public.sheets (
  sheet_number text primary key check (length(btrim(sheet_number)) between 1 and 80),
  status text not null default 'open' check (status in ('open', 'closed')),
  status_reason text not null default '',
  closed_at timestamptz,
  closed_by uuid references auth.users (id) on delete set null,
  updated_at timestamptz not null default pg_catalog.now(),
  updated_by uuid references auth.users (id) on delete set null,
  check ((status = 'closed') = (closed_at is not null))
);

alter table public.sheets enable row level security;
alter table public.sheets force row level security;
revoke all on table public.sheets from public, anon, authenticated;
grant select on table public.sheets to authenticated;
drop policy if exists approved_read_sheets on public.sheets;
create policy approved_read_sheets on public.sheets
  for select to authenticated using ((select private.is_approved_user()));

drop trigger if exists sheets_business_touch_updated_at on public.sheets;
create trigger sheets_business_touch_updated_at
  before update on public.sheets
  for each row execute function private.touch_business_updated_at();
drop trigger if exists sheets_business_audit on public.sheets;
create trigger sheets_business_audit
  after insert or update or delete on public.sheets
  for each row execute function private.write_business_audit();

create or replace function public.set_sheet_status(
  p_sheet_number text,
  p_is_closed boolean,
  p_reason text,
  p_expected_updated_at timestamptz
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_sheet text := nullif(btrim(p_sheet_number), '');
  v_existing public.sheets%rowtype;
  v_row public.sheets%rowtype;
begin
  if auth.uid() is null or not private.is_approved_user() then
    raise exception 'החשבון אינו מורשה לבצע פעולה זו.';
  end if;
  if v_sheet is null or p_is_closed is null then
    raise exception 'יש לבחור גיליון וסטטוס.';
  end if;
  if not exists (select 1 from public.orders where btrim(sheet_number) = v_sheet) then
    raise exception 'לגיליון זה אין הזמנות במערכת.';
  end if;
  if not p_is_closed and (p_reason is null or length(btrim(p_reason)) < 3) then
    raise exception 'נדרש הסבר קצר לפתיחה מחדש של גיליון סגור.';
  end if;

  select * into v_existing from public.sheets where sheet_number = v_sheet for update;
  if found and p_expected_updated_at is not null
     and v_existing.updated_at is distinct from p_expected_updated_at then
    raise exception using errcode = '40001',
      message = 'סטטוס הגיליון השתנה אצל משתמשת אחרת. רענני ונסי שוב.';
  end if;

  insert into public.sheets (sheet_number, status, status_reason, closed_at, closed_by, updated_by)
  values (
    v_sheet,
    case when p_is_closed then 'closed' else 'open' end,
    coalesce(btrim(p_reason), ''),
    case when p_is_closed then pg_catalog.now() else null end,
    case when p_is_closed then auth.uid() else null end,
    auth.uid()
  )
  on conflict (sheet_number) do update
    set status = excluded.status,
        status_reason = excluded.status_reason,
        closed_at = excluded.closed_at,
        closed_by = excluded.closed_by,
        updated_by = excluded.updated_by
  returning * into v_row;

  return jsonb_build_object('sheet_number', v_row.sheet_number, 'status', v_row.status, 'updated_at', v_row.updated_at);
end;
$function$;

revoke all on function public.set_sheet_status(text, boolean, text, timestamptz) from public, anon;
grant execute on function public.set_sheet_status(text, boolean, text, timestamptz) to authenticated;

do $realtime$
begin
  if exists (select 1 from pg_catalog.pg_publication where pubname = 'supabase_realtime')
     and not exists (
       select 1 from pg_catalog.pg_publication_tables
       where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'sheets'
     ) then
    execute 'alter publication supabase_realtime add table public.sheets';
  end if;
end
$realtime$;

commit;

-- Verification
select (select last_number from private.order_number_counters where counter_name = 'orders') as last_order_number,
       (select max(order_number) from public.orders) as highest_existing_order_number,
       pg_catalog.to_regclass('public.sheets') is not null as sheets_table_installed;


-- =====================================================================================================
-- supabase-orders-v3.sql
-- =====================================================================================================
-- =====================================================================================================
-- supabase-orders-v3.sql — orders, payments and packages: the working model of the newspaper.
--
-- NOT RUN. Requires the owner's explicit approval, a verified backup and a dry run on a separate test
-- project first (see INSTALL-ORDERS-V3.md). Run AFTER supabase-business-upgrade.sql and
-- supabase-sheets-and-order-numbers.sql. Independent of the sheets v2 files (may run before or after them).
--
-- What it adds (nothing is deleted, no existing amount, number, status or balance is rewritten):
--   orders                : ad_description (free text, required for new orders), file_status, placement_status
--                           ('unknown' for every existing order), documented cancellation (cancelled_at/by/reason).
--   financial_obligations : status 'cancelled' + cancellation fields, amount_before_vat (new rows only),
--                           received_at_cancel (keeps "money received" of a cancelled legacy paid order).
--   business_payment_events: received_on (receipt date) and reverses_event_id (one documented reversal per receipt).
--   credit_ledger         : entry types 'order_cancellation' (returned once per order, unique index) and
--                           'order_adjustment' (a documented change of the credits of an order).
--   functions             : create_orders_batch (new version: free description, product optional; old callers
--                           keep working), update_order_details, update_order_charge, cancel_business_order,
--                           record_obligation_payment (partial payments), reverse_obligation_payment,
--                           update_installment_schedule (edit unpaid installments after the purchase).
--   views                 : business_order_financial_summary / business_financial_summary / business_financial_totals
--                           are recreated with the same columns (+ new ones at the end): cancelled charges are no
--                           longer open debt, partial receipts are counted, history is kept.
--
-- Compatibility: the site that is live today (orders model v2) keeps working after this file: the old function
-- signatures are unchanged, set_obligation_paid / delete_business_order / update_business_order are untouched.
-- Payment methods are intentionally NOT added (owner decision; a future invoicing integration will add references).
-- Order numbering is untouched: no counter change, no renumbering.
-- One transaction: if anything fails, nothing is changed. Safe to run twice.
-- =====================================================================================================

begin;

-- ---------- 0. Preconditions ----------
do $preflight$
begin
  if to_regclass('public.financial_obligations') is null
     or to_regclass('public.business_payment_events') is null
     or to_regclass('public.credit_ledger') is null
     or to_regprocedure('public.create_orders_batch(text, jsonb, uuid)') is null
     or to_regprocedure('private.claim_business_operation(uuid, text, text)') is null
     or to_regprocedure('private.is_approved_user()') is null then
    raise exception 'The business schema is missing. Run supabase-business-upgrade.sql first.';
  end if;
end;
$preflight$;

-- ---------- 1. Orders: free description, workflow statuses, documented cancellation ----------
alter table public.orders
  add column if not exists ad_description text,
  add column if not exists file_status text not null default 'unknown',
  add column if not exists placement_status text not null default 'unknown',
  add column if not exists cancelled_at timestamptz,
  add column if not exists cancelled_by uuid references auth.users (id) on delete set null,
  add column if not exists cancel_reason text;

alter table public.orders
  drop constraint if exists orders_ad_description_check,
  drop constraint if exists orders_file_status_check,
  drop constraint if exists orders_placement_status_check,
  drop constraint if exists orders_cancellation_check,
  add constraint orders_ad_description_check
    check (ad_description is null or length(btrim(ad_description)) between 1 and 500),
  -- 'unknown' = an order from before this model; never inferred from other data.
  add constraint orders_file_status_check
    check (file_status in ('unknown', 'not_received', 'received', 'approved')),
  add constraint orders_placement_status_check
    check (placement_status in ('unknown', 'not_placed', 'placed', 'published')),
  add constraint orders_cancellation_check
    check ((cancelled_at is null and cancel_reason is null)
           or (cancelled_at is not null and length(btrim(coalesce(cancel_reason, ''))) >= 3));

create index if not exists orders_active_entered_idx
  on public.orders (entered_at desc) where cancelled_at is null;

-- ---------- 2. Financial obligations: cancellation, planned amount before VAT ----------
alter table public.financial_obligations
  add column if not exists amount_before_vat numeric(12, 2),
  add column if not exists cancelled_at timestamptz,
  add column if not exists cancelled_by uuid references auth.users (id) on delete set null,
  add column if not exists cancel_reason text,
  add column if not exists received_at_cancel numeric(12, 2);

-- The status check of the base migration is an unnamed column check; drop it by its definition.
do $obligation_checks$
declare
  v_name text;
begin
  for v_name in
    select conname from pg_catalog.pg_constraint
    where conrelid = 'public.financial_obligations'::regclass and contype = 'c'
      and (pg_catalog.pg_get_constraintdef(oid) like '%''pending''%''paid''%'
           and pg_catalog.pg_get_constraintdef(oid) not like '%paid_at%'
           and pg_catalog.pg_get_constraintdef(oid) not like '%cancelled%')
  loop
    execute pg_catalog.format('alter table public.financial_obligations drop constraint %I', v_name);
  end loop;
end;
$obligation_checks$;

alter table public.financial_obligations
  drop constraint if exists financial_obligations_status_check,
  drop constraint if exists financial_obligations_paid_timestamp_check,
  drop constraint if exists financial_obligations_cancellation_check,
  drop constraint if exists financial_obligations_amount_before_vat_check,
  add constraint financial_obligations_status_check
    check (status in ('pending', 'paid', 'cancelled')),
  add constraint financial_obligations_paid_timestamp_check
    check (
      (status = 'pending' and paid_at is null and paid_by is null)
      or (status = 'paid' and (
        (paid_at is not null and paid_by is not null)
        or (legacy_snapshot and paid_at is null and paid_by is null)
      ))
      or (status = 'cancelled')
    ),
  add constraint financial_obligations_cancellation_check
    check ((status = 'cancelled') = (cancelled_at is not null)
           and (status <> 'cancelled' or length(btrim(coalesce(cancel_reason, ''))) >= 3)),
  add constraint financial_obligations_amount_before_vat_check
    check (amount_before_vat is null or (amount_before_vat > 0 and amount_before_vat = round(amount_before_vat, 2)));

-- ---------- 3. Payment events: receipt date and a single documented reversal per receipt ----------
alter table public.business_payment_events
  add column if not exists received_on date,
  add column if not exists reverses_event_id uuid references public.business_payment_events (id) on delete restrict;

create unique index if not exists business_payment_events_one_reversal_uidx
  on public.business_payment_events (reverses_event_id) where reverses_event_id is not null;

-- ---------- 4. Credit ledger: cancellation (once per order) and documented adjustment of an order ----------
do $ledger_checks$
declare
  v_name text;
begin
  for v_name in
    select conname from pg_catalog.pg_constraint
    where conrelid = 'public.credit_ledger'::regclass and contype = 'c'
      and pg_catalog.pg_get_constraintdef(oid) like '%package_grant%'
  loop
    execute pg_catalog.format('alter table public.credit_ledger drop constraint %I', v_name);
  end loop;
end;
$ledger_checks$;

alter table public.credit_ledger
  add constraint credit_ledger_entry_type_check check (
    entry_type in ('package_grant', 'order_consumption', 'correction', 'conversion_reversal',
                   'order_cancellation', 'order_adjustment')
  ),
  add constraint credit_ledger_entry_shape_check check (
    (entry_type = 'package_grant' and customer_package_id is not null and order_id is null and delta > 0)
    or (entry_type = 'order_consumption' and order_id is not null and customer_package_id is null and delta < 0)
    or (entry_type = 'correction' and customer_package_id is null)
    or (entry_type = 'conversion_reversal' and order_id is null and customer_package_id is null)
    or (entry_type = 'order_cancellation' and order_id is not null and customer_package_id is null and delta > 0)
    or (entry_type = 'order_adjustment' and order_id is not null and customer_package_id is null)
  );

create unique index if not exists credit_ledger_one_cancellation_per_order_uidx
  on public.credit_ledger (order_id) where entry_type = 'order_cancellation';

-- ---------- 5. Private helpers ----------
-- Money received for one obligation: business receipts + receipts of the original payments table, or the
-- recorded legacy "paid" flag when there is no receipt record at all (same rule as the financial views).
create or replace function private.obligation_received(p_obligation_id uuid)
returns numeric
language sql
stable
security definer
set search_path = ''
as $function$
  select case
           when coalesce(e.n, 0) + coalesce(p.n, 0) = 0 and f.legacy_snapshot and f.status = 'paid'
             then f.amount_due
           when coalesce(e.n, 0) + coalesce(p.n, 0) = 0 and f.legacy_snapshot and f.status = 'cancelled'
             then coalesce(f.received_at_cancel, 0)
           else coalesce(e.s, 0) + coalesce(p.s, 0)
         end::numeric(12, 2)
  from public.financial_obligations as f
  left join lateral (
    select sum(events.amount) as s, count(*) as n
    from public.business_payment_events as events where events.obligation_id = f.id
  ) as e on true
  left join lateral (
    select sum(payments.amount) as s, count(*) as n
    from public.payments as payments where f.order_id is not null and payments.order_id = f.order_id
  ) as p on true
  where f.id = p_obligation_id;
$function$;

-- Paid in full = received >= amount due. Keeps orders.payment_status in step (paid / pending).
create or replace function private.refresh_obligation_status(p_obligation_id uuid)
returns text
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_obligation public.financial_obligations%rowtype;
  v_received numeric(12, 2);
  v_status text;
begin
  select * into v_obligation from public.financial_obligations where id = p_obligation_id for update;
  if not found then
    raise exception 'החיוב לא נמצא.';
  end if;
  if v_obligation.status = 'cancelled' then
    return 'cancelled';
  end if;
  v_received := private.obligation_received(p_obligation_id);
  v_status := case when v_received >= v_obligation.amount_due then 'paid' else 'pending' end;
  if v_status <> v_obligation.status then
    update public.financial_obligations
    set status = v_status,
        paid_at = case when v_status = 'paid' then pg_catalog.now() else null end,
        paid_by = case when v_status = 'paid' then auth.uid() else null end
    where id = p_obligation_id;
  end if;
  if v_obligation.order_id is not null then
    update public.orders set payment_status = v_status
    where id = v_obligation.order_id and payment_status <> v_status;
  end if;
  return v_status;
end;
$function$;

create or replace function private.require_approved_user()
returns void
language plpgsql
stable
security definer
set search_path = ''
as $function$
begin
  if auth.uid() is null or not private.is_approved_user() then
    raise exception 'החשבון אינו מורשה לבצע פעולה זו.';
  end if;
end;
$function$;

revoke all on function private.obligation_received(uuid) from public, anon, authenticated;
revoke all on function private.refresh_obligation_status(uuid) from public, anon, authenticated;
revoke all on function private.require_approved_user() from public, anon, authenticated;

-- The business day is the date in Israel. Supabase runs in UTC, so current_date is still "yesterday" between
-- 00:00 and 02:00/03:00 Israel time: an order entered then would get yesterday's date, and a charge due today
-- would not yet count as due. Every date decision in this file uses this function instead of current_date.
create or replace function private.business_today()
returns date
language sql
stable
set search_path = ''
as $function$
  select (pg_catalog.now() at time zone 'Asia/Jerusalem')::date
$function$;
revoke all on function private.business_today() from public, anon;
-- The financial views run with the caller's rights (security_invoker), so signed-in users may call it.
grant execute on function private.business_today() to authenticated;

-- Direct inserts (clients from the UI; orders only until the cut-over) get the Israel date too.
alter table public.orders alter column entered_at set default private.business_today();
alter table public.clients alter column joined_at set default private.business_today();

-- ---------- 6. create_orders_batch: free description, product optional ----------
-- Same signature and result as before. New rule: every row needs ad_description (1–500 characters).
-- Backward compatible: a row that names an active product but no description (the current live site) still
-- works; the product name becomes its description. New orders start as "file not received / not placed".
create or replace function public.create_orders_batch(
  p_client_id text,
  p_orders jsonb,
  p_idempotency_key uuid
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_cached jsonb;
  v_row jsonb;
  v_product public.product_catalog%rowtype;
  v_has_product boolean;
  v_client public.clients%rowtype;
  v_vat numeric(5, 4);
  v_cash numeric;
  v_credits numeric;
  v_amount numeric(12, 2);
  v_status text;
  v_id text;
  v_order_number bigint;
  v_obligation_id uuid;
  v_result jsonb := '[]'::jsonb;
  v_actor_label text;
  v_balance numeric;
  v_count integer := 0;
  v_sheet text;
  v_publication_date date;
  v_due_on date;
  v_description text;
begin
  perform private.require_approved_user();
  if p_client_id is null or p_orders is null
     or jsonb_typeof(p_orders) <> 'array'
     or jsonb_array_length(p_orders) = 0
     or jsonb_array_length(p_orders) > 250 then
    raise exception 'יש לבחור לקוח ולהוסיף בין הזמנה אחת ל-250 הזמנות.';
  end if;

  v_cached := private.claim_business_operation(
    p_idempotency_key, 'create_orders_batch',
    pg_catalog.md5(p_client_id || ':' || p_orders::text)
  );
  if v_cached is not null then
    return v_cached;
  end if;

  select * into v_client from public.clients where id = p_client_id for update;
  if not found then
    raise exception 'הלקוח לא נמצא.';
  end if;

  select vat_rate into v_vat from public.business_settings where singleton;
  if v_vat is null then
    raise exception 'הגדרת המע"מ חסרה.';
  end if;

  v_actor_label := coalesce(
    nullif(auth.jwt() -> 'user_metadata' ->> 'full_name', ''),
    nullif(auth.jwt() -> 'user_metadata' ->> 'name', ''),
    nullif(auth.jwt() ->> 'email', ''),
    'משתמשת'
  );

  for v_row in select value from jsonb_array_elements(p_orders)
  loop
    v_count := v_count + 1;
    if jsonb_typeof(v_row) <> 'object' then
      raise exception 'שורת הזמנה % אינה תקינה.', v_count;
    end if;

    v_cash := nullif(v_row ->> 'cash_amount_before_vat', '')::numeric;
    if v_cash is not null
       and (v_cash <= 0 or v_cash > 99999999 or round(v_cash, 2) <> v_cash) then
      raise exception 'המחיר בשורה % חייב להיות חיובי, עד 99,999,999 ש"ח, ובדיוק שתי ספרות אחרי הנקודה.', v_count;
    end if;
    v_credits := nullif(v_row ->> 'credits_used', '')::numeric;
    if (v_credits is not null and (v_credits <= 0 or round(v_credits, 2) <> v_credits))
       or ((v_cash is null) = (v_credits is null)) then
      raise exception 'בכל שורה יש למלא בדיוק ערך חיובי אחד: מחיר לפני מע"מ או קרדיטים.';
    end if;

    v_sheet := nullif(btrim(v_row ->> 'sheet_number'), '');
    if v_sheet is null or length(v_sheet) > 80 then
      raise exception 'יש להזין מספר גיליון תקין בשורה %.', v_count;
    end if;
    -- The legacy column is still NOT NULL; the newspaper has no per-order publication date, so the order
    -- date is used when none is sent.
    v_publication_date := coalesce(nullif(v_row ->> 'publication_date', '')::date, private.business_today());
    v_status := coalesce(v_row ->> 'payment_status', 'pending');
    if v_status not in ('paid', 'pending') then
      raise exception 'סטטוס התשלום בשורה % אינו תקין.', v_count;
    end if;
    v_due_on := nullif(v_row ->> 'due_on', '')::date;

    v_has_product := nullif(v_row ->> 'product_id', '') is not null;
    if v_has_product then
      select * into v_product
      from public.product_catalog
      where id = (v_row ->> 'product_id')::uuid and is_active
      for share;
      if not found then
        raise exception 'המוצר בשורה % אינו קיים או אינו פעיל.', v_count;
      end if;
    end if;

    v_description := nullif(btrim(coalesce(v_row ->> 'ad_description', '')), '');
    if v_description is null and v_has_product then
      v_description := v_product.name;
    end if;
    if v_description is null or length(v_description) > 500 then
      raise exception 'יש להזין פירוט הזמנה בשורה % (עד 500 תווים).', v_count;
    end if;
    if length(coalesce(v_row ->> 'notes', '')) > 5000 then
      raise exception 'ההערה בשורה % ארוכה מדי.', v_count;
    end if;

    if v_cash is not null then
      v_amount := round(v_cash * (1 + v_vat), 2);
    else
      v_amount := 0;
      v_status := 'paid';
    end if;

    insert into public.orders (
      id, client_id, publication_date, section, amount, payment_status, notes,
      entered_at, entered_by, entered_by_name, sheet_number, product_id,
      product_name_snapshot, product_dimensions_snapshot,
      product_price_snapshot, product_credit_cost_snapshot, billing_mode,
      cash_amount_before_vat, credits_used, vat_rate_snapshot,
      ad_description, file_status, placement_status
    )
    values (
      'o-' || gen_random_uuid()::text,
      p_client_id,
      v_publication_date,
      left(v_description, 120),
      v_amount,
      v_status,
      coalesce(v_row ->> 'notes', ''),
      private.business_today(),
      auth.uid(),
      v_actor_label,
      v_sheet,
      case when v_has_product then v_product.id else null end,
      case when v_has_product then v_product.name else null end,
      case when v_has_product then v_product.dimensions else null end,
      case when v_has_product then v_product.base_price_before_vat else null end,
      case when v_has_product then v_product.credit_cost else null end,
      case when v_cash is not null then 'cash' else 'credits' end,
      v_cash,
      v_credits,
      case when v_cash is not null then v_vat else null end,
      v_description,
      'not_received',
      'not_placed'
    )
    returning id, order_number into v_id, v_order_number;

    if v_credits is not null then
      insert into public.credit_ledger (
        client_id, delta, entry_type, order_id, reason, idempotency_key, created_by
      )
      values (
        p_client_id, -v_credits, 'order_consumption', v_id,
        'ניצול קרדיטים בהזמנה ' || v_order_number,
        gen_random_uuid(), auth.uid()
      );
      select coalesce(sum(delta), 0) into v_balance from public.credit_ledger where client_id = p_client_id;
      v_result := v_result || jsonb_build_array(jsonb_build_object(
        'id', v_id, 'order_number', v_order_number,
        'billing_mode', 'credits', 'credit_balance_after', v_balance
      ));
    else
      insert into public.financial_obligations (
        order_id, amount_due, amount_before_vat, due_on, status, paid_at, paid_by, created_by
      )
      values (
        v_id, v_amount, v_cash, v_due_on, v_status,
        case when v_status = 'paid' then pg_catalog.now() else null end,
        case when v_status = 'paid' then auth.uid() else null end,
        auth.uid()
      )
      returning id into v_obligation_id;

      if v_status = 'paid' then
        insert into public.business_payment_events (
          obligation_id, event_type, amount, notes, received_on, idempotency_key, created_by
        )
        values (
          v_obligation_id, 'payment', v_amount, 'סומן כשולם בעת יצירת ההזמנה',
          private.business_today(), gen_random_uuid(), auth.uid()
        );
      end if;
      v_result := v_result || jsonb_build_array(jsonb_build_object(
        'id', v_id, 'order_number', v_order_number,
        'billing_mode', 'cash', 'gross_amount', v_amount,
        'obligation_id', v_obligation_id
      ));
    end if;
  end loop;

  update private.business_operations set response = v_result where idempotency_key = p_idempotency_key;
  return v_result;
end;
$function$;

-- ---------- 7. update_order_details: non-financial fields (double-click editing) ----------
-- All fields are sent (the current value for an untouched field). An existing description cannot be
-- cleared; a legacy order may stay without one until someone writes it.
create or replace function public.update_order_details(
  p_order_id text,
  p_expected_updated_at timestamptz,
  p_ad_description text,
  p_notes text,
  p_sheet_number text,
  p_file_status text,
  p_placement_status text,
  p_idempotency_key uuid
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_cached jsonb;
  v_order public.orders%rowtype;
  v_description text := nullif(btrim(coalesce(p_ad_description, '')), '');
  v_sheet text := nullif(btrim(coalesce(p_sheet_number, '')), '');
  v_result jsonb;
begin
  perform private.require_approved_user();
  if p_order_id is null or p_expected_updated_at is null then
    raise exception 'חסר מזהה הגרסה של ההזמנה. יש לרענן את הנתונים.';
  end if;
  v_cached := private.claim_business_operation(
    p_idempotency_key, 'update_order_details',
    pg_catalog.md5(pg_catalog.jsonb_build_array(p_order_id, p_expected_updated_at, p_ad_description, p_notes,
      p_sheet_number, p_file_status, p_placement_status)::text)
  );
  if v_cached is not null then
    return v_cached;
  end if;

  select * into v_order from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'ההזמנה לא נמצאה.';
  end if;
  if v_order.updated_at <> p_expected_updated_at then
    raise exception using errcode = '40001',
      message = 'ההזמנה עודכנה אצל משתמש אחר. רענני את הנתונים ונסי שוב.';
  end if;
  if v_order.cancelled_at is not null then
    raise exception 'ההזמנה בוטלה ואינה ניתנת לעריכה.';
  end if;
  if v_description is null and v_order.ad_description is not null then
    raise exception 'פירוט ההזמנה הוא שדה חובה.';
  end if;
  if v_description is not null and length(v_description) > 500 then
    raise exception 'פירוט ההזמנה ארוך מ-500 תווים.';
  end if;
  if p_notes is null or length(p_notes) > 5000 then
    raise exception 'ההערה אינה תקינה.';
  end if;
  if v_sheet is not null and length(v_sheet) > 80 then
    raise exception 'מספר הגיליון אינו תקין.';
  end if;
  if v_sheet is null and v_order.sheet_number is not null then
    raise exception 'אי אפשר להסיר את הגיליון מהזמנה; אפשר להעביר אותה לגיליון אחר.';
  end if;
  if p_file_status not in ('unknown', 'not_received', 'received', 'approved')
     or p_placement_status not in ('unknown', 'not_placed', 'placed', 'published') then
    raise exception 'הסטטוס שנבחר אינו תקין.';
  end if;
  -- "unknown" is the state of an order from before this model; it is never chosen again once set.
  if (p_file_status = 'unknown' and v_order.file_status <> 'unknown')
     or (p_placement_status = 'unknown' and v_order.placement_status <> 'unknown') then
    raise exception 'אי אפשר להחזיר סטטוס ל"לא ידוע".';
  end if;

  update public.orders
  set ad_description = v_description,
      notes = p_notes,
      sheet_number = v_sheet,
      file_status = p_file_status,
      placement_status = p_placement_status
  where id = p_order_id
  returning * into v_order;

  v_result := pg_catalog.jsonb_build_object('id', v_order.id, 'order_number', v_order.order_number,
    'updated_at', v_order.updated_at);
  update private.business_operations set response = v_result where idempotency_key = p_idempotency_key;
  return v_result;
end;
$function$;

-- ---------- 8. update_order_charge: price before VAT of a cash order, or credits of a credits order ----------
-- Cash: the VAT rate saved in the order is kept; the charge may not drop below what was already received.
-- Credits: the difference is written as one 'order_adjustment' ledger entry (history is never rewritten).
-- Legacy orders (amount of unknown VAT basis) and cancelled orders are not changed here.
create or replace function public.update_order_charge(
  p_order_id text,
  p_expected_updated_at timestamptz,
  p_cash_amount_before_vat numeric,
  p_credits_used numeric,
  p_idempotency_key uuid
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_cached jsonb;
  v_order public.orders%rowtype;
  v_obligation public.financial_obligations%rowtype;
  v_amount numeric(12, 2);
  v_received numeric(12, 2);
  v_delta numeric;
  v_result jsonb;
begin
  perform private.require_approved_user();
  if p_order_id is null or p_expected_updated_at is null then
    raise exception 'חסר מזהה הגרסה של ההזמנה. יש לרענן את הנתונים.';
  end if;
  v_cached := private.claim_business_operation(
    p_idempotency_key, 'update_order_charge',
    pg_catalog.md5(pg_catalog.jsonb_build_array(p_order_id, p_expected_updated_at, p_cash_amount_before_vat,
      p_credits_used)::text)
  );
  if v_cached is not null then
    return v_cached;
  end if;

  select * into v_order from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'ההזמנה לא נמצאה.';
  end if;
  if v_order.updated_at <> p_expected_updated_at then
    raise exception using errcode = '40001',
      message = 'ההזמנה עודכנה אצל משתמש אחר. רענני את הנתונים ונסי שוב.';
  end if;
  if v_order.cancelled_at is not null then
    raise exception 'ההזמנה בוטלה ואינה ניתנת לעריכה.';
  end if;

  if v_order.billing_mode = 'cash' then
    if p_credits_used is not null then
      raise exception 'הזמנה כספית אינה יכולה לקבל קרדיטים. הזמנה היא כספית או בקרדיטים, לא שניהם.';
    end if;
    if p_cash_amount_before_vat is null or p_cash_amount_before_vat <= 0 or p_cash_amount_before_vat > 99999999
       or round(p_cash_amount_before_vat, 2) <> p_cash_amount_before_vat then
      raise exception 'המחיר לפני מע"מ חייב להיות חיובי, עם עד שתי ספרות אחרי הנקודה.';
    end if;
    v_amount := round(p_cash_amount_before_vat * (1 + v_order.vat_rate_snapshot), 2);
    select * into v_obligation from public.financial_obligations where order_id = p_order_id for update;
    if not found then
      raise exception 'חסר חיוב להזמנה; נדרשת בדיקת נתונים לפני עריכה.';
    end if;
    v_received := private.obligation_received(v_obligation.id);
    if v_amount < v_received then
      raise exception 'הסכום החדש כולל מע"מ (%) נמוך מהסכום שכבר התקבל (%). יש לבטל תקבול לפני הורדת המחיר.',
        v_amount, v_received;
    end if;
    update public.orders set cash_amount_before_vat = p_cash_amount_before_vat, amount = v_amount
    where id = p_order_id;
    update public.financial_obligations set amount_due = v_amount, amount_before_vat = p_cash_amount_before_vat
    where id = v_obligation.id;
    perform private.refresh_obligation_status(v_obligation.id);
  elsif v_order.billing_mode = 'credits' then
    if p_cash_amount_before_vat is not null then
      raise exception 'הזמנת קרדיטים אינה יכולה לקבל מחיר. הזמנה היא כספית או בקרדיטים, לא שניהם.';
    end if;
    if p_credits_used is null or p_credits_used <= 0 or round(p_credits_used, 2) <> p_credits_used then
      raise exception 'כמות הקרדיטים חייבת להיות חיובית, עם עד שתי ספרות אחרי הנקודה.';
    end if;
    v_delta := v_order.credits_used - p_credits_used;
    if v_delta <> 0 then
      update public.orders set credits_used = p_credits_used where id = p_order_id;
      insert into public.credit_ledger (client_id, delta, entry_type, order_id, reason, idempotency_key, created_by)
      values (v_order.client_id, v_delta, 'order_adjustment', p_order_id,
        'עדכון קרדיטים בהזמנה ' || v_order.order_number || ': ' || v_order.credits_used || ' → ' || p_credits_used,
        gen_random_uuid(), auth.uid());
    end if;
  else
    raise exception 'בהזמנה ישנה לא ידוע אם הסכום כולל מע"מ, ולכן אי אפשר לשנות את החיוב שלה כאן.';
  end if;

  select * into v_order from public.orders where id = p_order_id;
  v_result := pg_catalog.jsonb_build_object('id', v_order.id, 'order_number', v_order.order_number,
    'amount', v_order.amount, 'credits_used', v_order.credits_used, 'updated_at', v_order.updated_at);
  update private.business_operations set response = v_result where idempotency_key = p_idempotency_key;
  return v_result;
end;
$function$;

-- ---------- 9. cancel_business_order: documented cancellation instead of deletion ----------
-- The order stays in the database. Credits used are returned once (unique index); an open charge is cancelled;
-- money already received is kept and shown as such (a refund is recorded separately with
-- reverse_obligation_payment). Cancelling an order that is already cancelled changes nothing.
create or replace function public.cancel_business_order(
  p_order_id text,
  p_expected_updated_at timestamptz,
  p_reason text,
  p_idempotency_key uuid
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_cached jsonb;
  v_order public.orders%rowtype;
  v_obligation public.financial_obligations%rowtype;
  v_consumed numeric := 0;
  v_received numeric(12, 2) := 0;
  v_reason text := btrim(coalesce(p_reason, ''));
  v_result jsonb;
begin
  perform private.require_approved_user();
  if p_order_id is null then
    raise exception 'ההזמנה לא נמצאה.';
  end if;
  if length(v_reason) < 3 or length(v_reason) > 500 then
    raise exception 'נדרשת סיבת ביטול (3 עד 500 תווים).';
  end if;
  v_cached := private.claim_business_operation(
    p_idempotency_key, 'cancel_business_order',
    pg_catalog.md5(pg_catalog.jsonb_build_array(p_order_id, p_expected_updated_at, v_reason)::text)
  );
  if v_cached is not null then
    return v_cached;
  end if;

  select * into v_order from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'ההזמנה לא נמצאה.';
  end if;

  if v_order.cancelled_at is not null then
    v_result := pg_catalog.jsonb_build_object('id', v_order.id, 'order_number', v_order.order_number,
      'already_cancelled', true, 'credits_returned', 0, 'cash_received_kept', 0, 'updated_at', v_order.updated_at);
    update private.business_operations set response = v_result where idempotency_key = p_idempotency_key;
    return v_result;
  end if;
  if p_expected_updated_at is null or v_order.updated_at <> p_expected_updated_at then
    raise exception using errcode = '40001',
      message = 'ההזמנה עודכנה אצל משתמש אחר. רענני את הנתונים ונסי שוב.';
  end if;

  if v_order.billing_mode = 'credits' then
    select -coalesce(sum(delta), 0) into v_consumed
    from public.credit_ledger
    where order_id = p_order_id and entry_type in ('order_consumption', 'order_adjustment', 'order_cancellation');
    if v_consumed > 0 then
      insert into public.credit_ledger (client_id, delta, entry_type, order_id, reason, idempotency_key, created_by)
      values (v_order.client_id, v_consumed, 'order_cancellation', p_order_id,
        'החזרת קרדיטים בביטול הזמנה ' || v_order.order_number || ': ' || v_reason,
        gen_random_uuid(), auth.uid());
    end if;
  else
    select * into v_obligation from public.financial_obligations where order_id = p_order_id for update;
    if found and v_obligation.status <> 'cancelled' then
      v_received := private.obligation_received(v_obligation.id);
      update public.financial_obligations
      set status = 'cancelled', cancelled_at = pg_catalog.now(), cancelled_by = auth.uid(),
          cancel_reason = v_reason, received_at_cancel = v_received
      where id = v_obligation.id;
    end if;
  end if;

  update public.orders
  set cancelled_at = pg_catalog.now(), cancelled_by = auth.uid(), cancel_reason = v_reason
  where id = p_order_id
  returning * into v_order;

  v_result := pg_catalog.jsonb_build_object('id', v_order.id, 'order_number', v_order.order_number,
    'already_cancelled', false, 'credits_returned', greatest(v_consumed, 0),
    'cash_received_kept', v_received, 'updated_at', v_order.updated_at);
  update private.business_operations set response = v_result where idempotency_key = p_idempotency_key;
  return v_result;
end;
$function$;

-- ---------- 10. record_obligation_payment: a receipt (full or partial) ----------
-- Each receipt is a separate event; nothing is overwritten. More than the open balance is refused.
create or replace function public.record_obligation_payment(
  p_obligation_id uuid,
  p_amount numeric,
  p_received_on date,
  p_notes text,
  p_expected_updated_at timestamptz,
  p_idempotency_key uuid
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_cached jsonb;
  v_obligation public.financial_obligations%rowtype;
  v_received numeric(12, 2);
  v_outstanding numeric(12, 2);
  v_status text;
  v_result jsonb;
begin
  perform private.require_approved_user();
  if p_obligation_id is null or p_expected_updated_at is null then
    raise exception 'חסר מזהה הגרסה של החיוב. יש לרענן את הנתונים.';
  end if;
  if p_amount is null or p_amount <= 0 or p_amount > 99999999 or round(p_amount, 2) <> p_amount then
    raise exception 'סכום התקבול חייב להיות חיובי, עם עד שתי ספרות אחרי הנקודה.';
  end if;
  if p_received_on is null or p_received_on > private.business_today() + 1 then
    raise exception 'תאריך התקבול אינו תקין.';
  end if;
  if length(coalesce(p_notes, '')) > 500 then
    raise exception 'ההערה ארוכה מ-500 תווים.';
  end if;
  v_cached := private.claim_business_operation(
    p_idempotency_key, 'record_obligation_payment',
    pg_catalog.md5(pg_catalog.jsonb_build_array(p_obligation_id, p_amount, p_received_on, p_notes,
      p_expected_updated_at)::text)
  );
  if v_cached is not null then
    return v_cached;
  end if;

  select * into v_obligation from public.financial_obligations where id = p_obligation_id for update;
  if not found then
    raise exception 'החיוב לא נמצא.';
  end if;
  if v_obligation.updated_at <> p_expected_updated_at then
    raise exception using errcode = '40001',
      message = 'החיוב עודכן אצל משתמש אחר. רענני את הנתונים ונסי שוב.';
  end if;
  if v_obligation.status = 'cancelled' then
    raise exception 'החיוב בוטל; אי אפשר לרשום עליו תקבול.';
  end if;
  v_received := private.obligation_received(p_obligation_id);
  v_outstanding := v_obligation.amount_due - v_received;
  if v_outstanding <= 0 then
    raise exception 'החיוב כבר שולם במלואו.';
  end if;
  if p_amount > v_outstanding then
    raise exception 'הסכום גבוה מהיתרה לתשלום (% ש"ח). גבייה מעבר לחיוב אינה נרשמת כאן.', v_outstanding;
  end if;

  insert into public.business_payment_events (
    obligation_id, event_type, amount, event_at, received_on, notes, idempotency_key, created_by
  )
  values (
    p_obligation_id, 'payment', p_amount,
    (p_received_on::timestamp + interval '12 hours') at time zone 'Asia/Jerusalem',
    p_received_on, btrim(coalesce(p_notes, '')), gen_random_uuid(), auth.uid()
  );
  v_status := private.refresh_obligation_status(p_obligation_id);
  -- Make the new version visible to optimistic-concurrency checks even when the status did not change.
  update public.financial_obligations set updated_at = pg_catalog.now()
  where id = p_obligation_id returning * into v_obligation;

  v_received := private.obligation_received(p_obligation_id);
  v_result := pg_catalog.jsonb_build_object('obligation_id', p_obligation_id, 'status', v_status,
    'received', v_received, 'outstanding', greatest(v_obligation.amount_due - v_received, 0),
    'updated_at', v_obligation.updated_at);
  update private.business_operations set response = v_result where idempotency_key = p_idempotency_key;
  return v_result;
end;
$function$;

-- ---------- 11. reverse_obligation_payment: documented reversal / refund of one receipt ----------
create or replace function public.reverse_obligation_payment(
  p_event_id uuid,
  p_reason text,
  p_idempotency_key uuid
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_cached jsonb;
  v_event public.business_payment_events%rowtype;
  v_obligation public.financial_obligations%rowtype;
  v_reason text := btrim(coalesce(p_reason, ''));
  v_status text;
  v_received numeric(12, 2);
  v_result jsonb;
begin
  perform private.require_approved_user();
  if length(v_reason) < 3 or length(v_reason) > 500 then
    raise exception 'נדרשת סיבה לביטול התקבול (3 עד 500 תווים).';
  end if;
  v_cached := private.claim_business_operation(
    p_idempotency_key, 'reverse_obligation_payment',
    pg_catalog.md5(pg_catalog.jsonb_build_array(p_event_id, v_reason)::text)
  );
  if v_cached is not null then
    return v_cached;
  end if;

  select * into v_event from public.business_payment_events where id = p_event_id;
  if not found or v_event.event_type <> 'payment' then
    raise exception 'התקבול לא נמצא.';
  end if;
  select * into v_obligation from public.financial_obligations where id = v_event.obligation_id for update;
  if exists (select 1 from public.business_payment_events where reverses_event_id = p_event_id) then
    raise exception 'התקבול הזה כבר בוטל.';
  end if;

  insert into public.business_payment_events (
    obligation_id, event_type, amount, received_on, notes, reverses_event_id, idempotency_key, created_by
  )
  values (
    v_event.obligation_id, 'reversal', -v_event.amount, private.business_today(), v_reason, p_event_id,
    gen_random_uuid(), auth.uid()
  );
  v_status := private.refresh_obligation_status(v_event.obligation_id);
  update public.financial_obligations set updated_at = pg_catalog.now()
  where id = v_event.obligation_id returning * into v_obligation;
  v_received := private.obligation_received(v_event.obligation_id);

  v_result := pg_catalog.jsonb_build_object('obligation_id', v_event.obligation_id, 'status', v_status,
    'received', v_received, 'updated_at', v_obligation.updated_at);
  update private.business_operations set response = v_result where idempotency_key = p_idempotency_key;
  return v_result;
end;
$function$;

-- ---------- 12. update_installment_schedule: change unpaid installments after the purchase ----------
-- p_items = the complete new schedule: [{ "obligation_id": uuid|null, "due_on": date, "amount_before_vat": n }].
--   * A fully paid installment must appear unchanged (its receipts are history).
--   * A partly paid installment may change, but not below what was received.
--   * An unpaid installment that is left out is cancelled (kept as history), never deleted.
--   * A new row (no obligation_id) adds an installment.
--   * The amounts before VAT of all active installments must equal the package price.
-- package_installments is append-only, so the current amount and date live on the obligation.
create or replace function public.update_installment_schedule(
  p_customer_package_id uuid,
  p_expected_updated_at timestamptz,
  p_items jsonb,
  p_reason text,
  p_idempotency_key uuid
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_cached jsonb;
  v_package public.customer_packages%rowtype;
  v_reason text := btrim(coalesce(p_reason, ''));
  v_item jsonb;
  v_current record;
  v_id uuid;
  v_due date;
  v_net numeric;
  v_gross numeric(12, 2);
  v_received numeric(12, 2);
  v_seen uuid[] := '{}';
  v_sum_net numeric := 0;
  v_next_number integer;
  v_installment_id uuid;
  v_count integer := 0;
  v_result jsonb;
begin
  perform private.require_approved_user();
  if p_customer_package_id is null or p_expected_updated_at is null then
    raise exception 'חסר מזהה הגרסה של החבילה. יש לרענן את הנתונים.';
  end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array'
     or jsonb_array_length(p_items) < 1 or jsonb_array_length(p_items) > 60 then
    raise exception 'לוח התשלומים צריך לכלול בין תשלום אחד ל-60 תשלומים.';
  end if;
  if length(v_reason) < 3 or length(v_reason) > 500 then
    raise exception 'נדרשת סיבה לשינוי לוח התשלומים (3 עד 500 תווים).';
  end if;
  v_cached := private.claim_business_operation(
    p_idempotency_key, 'update_installment_schedule',
    pg_catalog.md5(pg_catalog.jsonb_build_array(p_customer_package_id, p_expected_updated_at, p_items, v_reason)::text)
  );
  if v_cached is not null then
    return v_cached;
  end if;

  select * into v_package from public.customer_packages where id = p_customer_package_id for update;
  if not found then
    raise exception 'החבילה לא נמצאה.';
  end if;
  if v_package.updated_at <> p_expected_updated_at then
    raise exception using errcode = '40001',
      message = 'החבילה עודכנה אצל משתמש אחר. רענני את הנתונים ונסי שוב.';
  end if;
  if v_package.status = 'cancelled' then
    raise exception 'החבילה בוטלה; אי אפשר לשנות את לוח התשלומים שלה.';
  end if;

  -- Validate every item first.
  for v_item in select value from jsonb_array_elements(p_items)
  loop
    v_count := v_count + 1;
    v_due := nullif(v_item ->> 'due_on', '')::date;
    v_net := nullif(v_item ->> 'amount_before_vat', '')::numeric;
    if v_due is null or v_net is null or v_net <= 0 or v_net > 99999999 or round(v_net, 2) <> v_net then
      raise exception 'תשלום % אינו תקין: נדרשים מועד וסכום חיובי לפני מע"מ.', v_count;
    end if;
    v_id := nullif(v_item ->> 'obligation_id', '')::uuid;
    if v_id is not null then
      if v_id = any (v_seen) then
        raise exception 'תשלום % מופיע פעמיים.', v_count;
      end if;
      v_seen := v_seen || v_id;
      perform 1
      from public.financial_obligations as f
      join public.package_installments as i on i.id = f.package_installment_id
      where f.id = v_id and i.customer_package_id = p_customer_package_id and f.status <> 'cancelled';
      if not found then
        raise exception 'תשלום % אינו שייך לחבילה הזו.', v_count;
      end if;
    end if;
    v_sum_net := v_sum_net + v_net;
  end loop;
  if v_sum_net <> v_package.price_before_vat then
    raise exception 'סכום התשלומים לפני מע"מ (%) חייב להיות שווה למחיר החבילה (%).', v_sum_net, v_package.price_before_vat;
  end if;

  -- Existing active installments: unchanged if paid, updated if listed, cancelled if left out.
  for v_current in
    select f.id, f.status, f.amount_due, f.due_on,
           coalesce(f.amount_before_vat, i.amount_before_vat) as net
    from public.financial_obligations as f
    join public.package_installments as i on i.id = f.package_installment_id
    where i.customer_package_id = p_customer_package_id and f.status <> 'cancelled'
    for update of f
  loop
    v_received := private.obligation_received(v_current.id);
    v_item := null; -- SELECT INTO keeps the old value when nothing matches
    select value into v_item from jsonb_array_elements(p_items) as e(value)
    where nullif(value ->> 'obligation_id', '')::uuid = v_current.id;
    if v_item is null then
      if v_received > 0 then
        raise exception 'אי אפשר להסיר תשלום שכבר התקבל עליו כסף (% ש"ח).', v_received;
      end if;
      update public.financial_obligations
      set status = 'cancelled', cancelled_at = pg_catalog.now(), cancelled_by = auth.uid(),
          cancel_reason = 'שינוי לוח תשלומים: ' || v_reason, received_at_cancel = 0
      where id = v_current.id;
    else
      v_due := (v_item ->> 'due_on')::date;
      v_net := (v_item ->> 'amount_before_vat')::numeric;
      v_gross := round(v_net * (1 + v_package.vat_rate_snapshot), 2);
      if v_current.status = 'paid' then
        if v_net <> v_current.net or v_due <> v_current.due_on then
          raise exception 'תשלום שהתקבל במלואו אינו ניתן לשינוי.';
        end if;
      else
        if v_gross < v_received then
          raise exception 'סכום התשלום כולל מע"מ (%) נמוך מהסכום שכבר התקבל עליו (%).', v_gross, v_received;
        end if;
        if v_net <> v_current.net or v_due is distinct from v_current.due_on then
          update public.financial_obligations
          set amount_due = v_gross, amount_before_vat = v_net, due_on = v_due
          where id = v_current.id;
          perform private.refresh_obligation_status(v_current.id);
        end if;
      end if;
    end if;
    v_item := null;
  end loop;

  -- New installments.
  select coalesce(max(installment_number), 0) into v_next_number
  from public.package_installments where customer_package_id = p_customer_package_id;
  for v_item in select value from jsonb_array_elements(p_items)
  loop
    if nullif(v_item ->> 'obligation_id', '') is null then
      v_next_number := v_next_number + 1;
      v_due := (v_item ->> 'due_on')::date;
      v_net := (v_item ->> 'amount_before_vat')::numeric;
      v_gross := round(v_net * (1 + v_package.vat_rate_snapshot), 2);
      insert into public.package_installments (
        customer_package_id, installment_number, due_on, amount_before_vat, vat_rate_snapshot, amount_due
      )
      values (p_customer_package_id, v_next_number, v_due, v_net, v_package.vat_rate_snapshot, v_gross)
      returning id into v_installment_id;
      insert into public.financial_obligations (
        package_installment_id, amount_due, amount_before_vat, due_on, status, created_by
      )
      values (v_installment_id, v_gross, v_net, v_due, 'pending', auth.uid());
    end if;
  end loop;

  update public.customer_packages as p
  set installment_count = s.n, gross_total = s.gross
  from (
    select count(*)::integer as n, sum(f.amount_due) as gross
    from public.financial_obligations as f
    join public.package_installments as i on i.id = f.package_installment_id
    where i.customer_package_id = p_customer_package_id and f.status <> 'cancelled'
  ) as s
  where p.id = p_customer_package_id
  returning p.* into v_package;

  v_result := pg_catalog.jsonb_build_object('customer_package_id', p_customer_package_id,
    'installment_count', v_package.installment_count, 'gross_total', v_package.gross_total,
    'updated_at', v_package.updated_at);
  update private.business_operations set response = v_result where idempotency_key = p_idempotency_key;
  return v_result;
end;
$function$;

-- ---------- 13. Financial views: one source for every money figure on every screen ----------
-- Same columns as before (in the same order) plus new ones at the end. A cancelled charge is no longer open
-- debt: its "due" equals the money actually kept, so outstanding is 0 and history stays visible.
drop view if exists public.business_financial_totals;
drop view if exists public.business_financial_summary;
drop view if exists public.business_order_financial_summary;

create view public.business_order_financial_summary
with (security_invoker = true)
as
select
  b.order_id,
  b.client_id,
  b.order_number,
  b.publication_date,
  b.section,
  b.sheet_number,
  b.billing_mode,
  (case when b.billing_mode = 'credits' then 0
        when b.is_cancelled then b.received
        else b.due_full end)::numeric as cash_due,
  b.received::numeric as cash_received,
  b.due_on,
  (case when b.is_cancelled then 'cancelled' else b.status end)::text as payment_status,
  b.legacy_snapshot,
  b.receipt_basis,
  b.has_payment_history,
  b.missing_obligation,
  (not b.is_cancelled and (
     (b.status = 'paid' and b.due_full > b.received)
     or (b.status = 'pending' and b.due_full > 0 and b.received >= b.due_full)
  )) as payment_status_mismatch,
  b.obligation_id,
  b.is_cancelled,
  b.ad_description,
  b.obligation_updated_at
from (
  select
    orders.id as order_id,
    orders.client_id,
    orders.order_number,
    orders.publication_date,
    orders.section,
    orders.sheet_number,
    orders.billing_mode,
    orders.ad_description,
    obligations.id as obligation_id,
    obligations.updated_at as obligation_updated_at,
    (orders.cancelled_at is not null or obligations.status = 'cancelled') as is_cancelled,
    case when orders.billing_mode = 'credits' then 0::numeric
         else coalesce(obligations.amount_due, orders.amount)::numeric end as due_full,
    case
      when orders.billing_mode = 'legacy' and orders.amount = 0 then 0::numeric
      when orders.billing_mode = 'credits' then 0::numeric
      when payments.payment_count + events.event_count = 0 and obligations.legacy_snapshot
           and obligations.status = 'paid' then obligations.amount_due::numeric
      when payments.payment_count + events.event_count = 0 and obligations.legacy_snapshot
           and obligations.status = 'cancelled' then coalesce(obligations.received_at_cancel, 0)::numeric
      else (payments.received + events.received)::numeric
    end as received,
    obligations.due_on,
    coalesce(obligations.status, orders.payment_status) as status,
    coalesce(obligations.legacy_snapshot, orders.billing_mode = 'legacy') as legacy_snapshot,
    case
      when orders.billing_mode = 'legacy' and orders.amount = 0 then 'non_cash_order'
      when payments.payment_count > 0 and events.event_count > 0 then 'combined_records'
      when payments.payment_count > 0 then 'public_payments'
      when events.event_count > 0 then 'business_payment_events'
      when obligations.legacy_snapshot and obligations.status in ('paid', 'cancelled')
        then 'legacy_paid_status_without_receipt_date'
      else 'no_receipt_record'
    end as receipt_basis,
    payments.payment_count > 0 or events.event_count > 0 as has_payment_history,
    obligations.id is null
      and orders.billing_mode <> 'credits'
      and not (orders.billing_mode = 'legacy' and orders.amount = 0) as missing_obligation
  from public.orders as orders
  left join public.financial_obligations as obligations on obligations.order_id = orders.id
  left join lateral (
    select coalesce(sum(payments.amount), 0)::numeric(12, 2) as received, count(*)::integer as payment_count
    from public.payments as payments where payments.order_id = orders.id
  ) as payments on true
  left join lateral (
    select coalesce(sum(events.amount), 0)::numeric(12, 2) as received, count(*)::integer as event_count
    from public.business_payment_events as events where events.obligation_id = obligations.id
  ) as events on true
) as b;

create view public.business_financial_summary
with (security_invoker = true)
as
select
  'order'::text as item_type,
  orders.order_id as item_id,
  orders.client_id,
  orders.order_number,
  orders.sheet_number,
  orders.section as description,
  orders.publication_date as item_date,
  orders.billing_mode,
  orders.cash_due,
  orders.cash_received,
  greatest(orders.cash_due - orders.cash_received, 0)::numeric(12, 2) as cash_outstanding,
  orders.due_on,
  orders.payment_status,
  case when greatest(orders.cash_due - orders.cash_received, 0) > 0 and orders.due_on < private.business_today()
       then greatest(orders.cash_due - orders.cash_received, 0) else 0::numeric end::numeric(12, 2) as overdue_amount,
  case when greatest(orders.cash_due - orders.cash_received, 0) > 0 and orders.due_on > private.business_today()
       then greatest(orders.cash_due - orders.cash_received, 0) else 0::numeric end::numeric(12, 2) as future_amount,
  case when greatest(orders.cash_due - orders.cash_received, 0) > 0 and orders.due_on = private.business_today()
       then greatest(orders.cash_due - orders.cash_received, 0) else 0::numeric end::numeric(12, 2) as due_today_amount,
  case when greatest(orders.cash_due - orders.cash_received, 0) > 0 and orders.due_on is null
       then greatest(orders.cash_due - orders.cash_received, 0) else 0::numeric end::numeric(12, 2) as no_due_date_amount,
  orders.legacy_snapshot,
  orders.receipt_basis,
  orders.has_payment_history,
  orders.missing_obligation,
  orders.payment_status_mismatch,
  orders.obligation_id,
  orders.is_cancelled,
  null::uuid as customer_package_id,
  orders.obligation_updated_at
from public.business_order_financial_summary as orders
union all
select
  'package_installment'::text,
  installments.id::text,
  packages.client_id,
  null::bigint,
  null::text,
  packages.package_name_snapshot || ' - תשלום ' || installments.installment_number::text,
  installments.due_on,
  'package'::text,
  x.cash_due,
  x.received,
  greatest(x.cash_due - x.received, 0)::numeric(12, 2),
  obligations.due_on,
  (case when x.is_cancelled then 'cancelled' else obligations.status end)::text,
  case when greatest(x.cash_due - x.received, 0) > 0 and obligations.due_on < private.business_today()
       then greatest(x.cash_due - x.received, 0) else 0::numeric end::numeric(12, 2),
  case when greatest(x.cash_due - x.received, 0) > 0 and obligations.due_on > private.business_today()
       then greatest(x.cash_due - x.received, 0) else 0::numeric end::numeric(12, 2),
  case when greatest(x.cash_due - x.received, 0) > 0 and obligations.due_on = private.business_today()
       then greatest(x.cash_due - x.received, 0) else 0::numeric end::numeric(12, 2),
  0::numeric(12, 2),
  false,
  case when events.event_count > 0 then 'business_payment_events' else 'no_receipt_record' end,
  events.event_count > 0,
  false,
  false,
  obligations.id,
  x.is_cancelled,
  packages.id,
  obligations.updated_at
from public.package_installments as installments
join public.customer_packages as packages on packages.id = installments.customer_package_id
join public.financial_obligations as obligations on obligations.package_installment_id = installments.id
left join lateral (
  select coalesce(sum(events.amount), 0)::numeric(12, 2) as received, count(*)::integer as event_count
  from public.business_payment_events as events where events.obligation_id = obligations.id
) as events on true
cross join lateral (
  select obligations.status = 'cancelled' as is_cancelled,
         events.received::numeric as received,
         (case when obligations.status = 'cancelled' then events.received
               else obligations.amount_due end)::numeric as cash_due
) as x;

create view public.business_financial_totals
with (security_invoker = true)
as
select
  count(*) filter (where item_type = 'order')::bigint as order_count,
  count(*) filter (where item_type = 'package_installment')::bigint as installment_count,
  coalesce(sum(cash_due), 0)::numeric(14, 2) as total_cash_billed,
  coalesce(sum(cash_received), 0)::numeric(14, 2) as total_cash_received,
  coalesce(sum(cash_outstanding), 0)::numeric(14, 2) as total_cash_outstanding,
  coalesce(sum(overdue_amount), 0)::numeric(14, 2) as total_overdue,
  coalesce(sum(future_amount), 0)::numeric(14, 2) as total_future,
  coalesce(sum(due_today_amount), 0)::numeric(14, 2) as total_due_today,
  coalesce(sum(no_due_date_amount), 0)::numeric(14, 2) as total_without_due_date,
  count(*) filter (where legacy_snapshot)::bigint as legacy_order_count,
  count(*) filter (where missing_obligation)::bigint as orders_missing_obligation,
  count(*) filter (where payment_status_mismatch)::bigint as payment_status_mismatches
from public.business_financial_summary;

revoke all on public.business_order_financial_summary, public.business_financial_summary,
  public.business_financial_totals from public, anon;
grant select on public.business_order_financial_summary, public.business_financial_summary,
  public.business_financial_totals to authenticated;

-- ---------- 14. Function permissions ----------
revoke all on function public.create_orders_batch(text, jsonb, uuid) from public, anon;
grant execute on function public.create_orders_batch(text, jsonb, uuid) to authenticated;
revoke all on function public.update_order_details(text, timestamptz, text, text, text, text, text, uuid) from public, anon;
grant execute on function public.update_order_details(text, timestamptz, text, text, text, text, text, uuid) to authenticated;
revoke all on function public.update_order_charge(text, timestamptz, numeric, numeric, uuid) from public, anon;
grant execute on function public.update_order_charge(text, timestamptz, numeric, numeric, uuid) to authenticated;
revoke all on function public.cancel_business_order(text, timestamptz, text, uuid) from public, anon;
grant execute on function public.cancel_business_order(text, timestamptz, text, uuid) to authenticated;
revoke all on function public.record_obligation_payment(uuid, numeric, date, text, timestamptz, uuid) from public, anon;
grant execute on function public.record_obligation_payment(uuid, numeric, date, text, timestamptz, uuid) to authenticated;
revoke all on function public.reverse_obligation_payment(uuid, text, uuid) from public, anon;
grant execute on function public.reverse_obligation_payment(uuid, text, uuid) to authenticated;
revoke all on function public.update_installment_schedule(uuid, timestamptz, jsonb, text, uuid) from public, anon;
grant execute on function public.update_installment_schedule(uuid, timestamptz, jsonb, text, uuid) to authenticated;

-- ---------- 15. Final check inside the transaction ----------
do $final$
begin
  if exists (select 1 from public.orders where file_status is null or placement_status is null) then
    raise exception 'Workflow status backfill failed.';
  end if;
  perform 1 from public.business_financial_totals;
end;
$final$;

commit;


-- =====================================================================================================
-- supabase-sheets-v2.sql
-- =====================================================================================================
-- Sheets model v2 — STAGE A (additive). REQUIRES THE OWNER'S EXPLICIT APPROVAL. Do not run without it.
-- Run order: supabase-sheets-v2-preflight.sql (read only) → THIS FILE → supabase-sheets-v2-verify.sql.
-- Enforcement (FK + closed-sheet trigger) is a separate later file: supabase-sheets-v2-enforce.sql.
--
-- What this file does
--   1. public.sheets becomes the official list of sheets: publication date, closing time (closes_at),
--      description, creation info and reopen info. A sheet can exist with zero orders.
--   2. Backfill: every sheet number already used in orders gets a row.
--      Historical sheets are CLOSED (they were published). Publication date stays EMPTY (never invented).
--      Sheets listed in the keep-open list below are created OPEN. Existing rows are never changed.
--   3. Effective state: a sheet is closed when status = 'closed' (manual) OR closes_at <= now() (deadline,
--      Friday 00:00 Asia/Jerusalem by default). No scheduler is needed; the server clock decides.
--   4. RPCs: create_sheets_batch (all-or-nothing), update_sheet_details, set_sheet_state (close / reopen with a
--      reason and a new future closing time). The old set_sheet_status keeps working for the current UI.
--   5. View public.sheet_overview (read only, RLS of public.sheets applies) with is_closed and the server time.
--
-- What this file does NOT do
--   - No change to orders, payments, obligations, credits or packages.
--   - No blocking of orders yet (that is supabase-sheets-v2-enforce.sql, after the new UI is published).
--   - No renaming or normalising of existing sheet numbers.
--
-- Safe to run twice (a second run adds nothing).

begin;

-- =====================================================================
-- 0. OWNER INPUT — REVIEW BEFORE RUNNING
-- =====================================================================
-- Sheets that must stay OPEN after the migration: the active sheet for orders, and any future sheet that
-- already has orders. Take them from the preflight result (column recent_activity / last_order_date).
-- Replace the placeholder with real numbers, e.g.:  values ('142'), ('143');
-- To keep NO sheet open, delete the whole insert statement (the recent-activity guard below still applies).
create temporary table sheets_v2_keep_open (sheet_number text primary key) on commit drop;
-- (empty project: no sheet to keep open)

-- Safety net: the migration stops if it would close a sheet that had orders entered in the last
-- 14 days and is not in the keep-open list. Set to true ONLY after checking that list on purpose.
create temporary table sheets_v2_settings (confirm_close_recent boolean not null) on commit drop;
insert into sheets_v2_settings (confirm_close_recent) values (false);

-- =====================================================================
-- Preflight checks (stop before any change)
-- =====================================================================
do $preflight$
declare
  v_missing text;
  v_recent text;
begin
  if pg_catalog.to_regclass('public.sheets') is null
     or pg_catalog.to_regprocedure('public.set_sheet_status(text, boolean, text, timestamp with time zone)') is null then
    raise exception 'Run supabase-sheets-and-order-numbers.sql first (public.sheets is missing).';
  end if;
  if pg_catalog.to_regprocedure('private.is_approved_user()') is null
     or pg_catalog.to_regprocedure('private.claim_business_operation(uuid, text, text)') is null then
    raise exception 'Run supabase-business-upgrade.sql first.';
  end if;
  if exists (select 1 from sheets_v2_keep_open where sheet_number like '\_\_%') then
    raise exception 'Edit the keep-open list at the top of this file (placeholder still present). Nothing was changed.';
  end if;

  select string_agg(keep.sheet_number, ', ') into v_missing
  from sheets_v2_keep_open as keep
  where not exists (select 1 from public.orders where pg_catalog.btrim(orders.sheet_number) = keep.sheet_number)
    and not exists (select 1 from public.sheets where sheets.sheet_number = keep.sheet_number);
  if v_missing is not null then
    raise exception 'Keep-open sheet(s) not found in orders or sheets: %. Check for typos. Nothing was changed.', v_missing;
  end if;

  if not (select confirm_close_recent from sheets_v2_settings) then
    select string_agg(recent.sheet_number, ', ' order by recent.sheet_number) into v_recent
    from (
      select pg_catalog.btrim(orders.sheet_number) as sheet_number
      from public.orders
      where pg_catalog.btrim(coalesce(orders.sheet_number, '')) <> ''
        and coalesce(orders.entered_at, (orders.created_at at time zone 'Asia/Jerusalem')::date)
            >= (pg_catalog.now() at time zone 'Asia/Jerusalem')::date - 14
      group by 1
    ) as recent
    where not exists (select 1 from sheets_v2_keep_open as keep where keep.sheet_number = recent.sheet_number)
      and not exists (select 1 from public.sheets where sheets.sheet_number = recent.sheet_number);
    if v_recent is not null then
      raise exception 'These sheets had orders in the last 14 days and would be CLOSED: %. Add the active one(s) to the keep-open list, or set confirm_close_recent = true on purpose. Nothing was changed.', v_recent;
    end if;
  end if;
end
$preflight$;

-- =====================================================================
-- 1. Columns
-- =====================================================================
alter table public.sheets
  add column if not exists publication_date date,
  add column if not exists closes_at timestamptz,
  add column if not exists description text not null default '',
  add column if not exists created_at timestamptz not null default pg_catalog.now(),
  add column if not exists created_by uuid references auth.users (id) on delete set null,
  -- status: rows created by the old set_sheet_status; backfill: created by this migration; planned: "הוספת גיליונות".
  add column if not exists created_via text not null default 'status',
  add column if not exists reopened_at timestamptz,
  add column if not exists reopened_by uuid references auth.users (id) on delete set null;

do $constraints$
begin
  if not exists (select 1 from pg_catalog.pg_constraint
                 where conrelid = 'public.sheets'::regclass and conname = 'sheets_description_length') then
    alter table public.sheets add constraint sheets_description_length check (pg_catalog.length(description) <= 200);
  end if;
  if not exists (select 1 from pg_catalog.pg_constraint
                 where conrelid = 'public.sheets'::regclass and conname = 'sheets_created_via_check') then
    alter table public.sheets add constraint sheets_created_via_check check (created_via in ('status', 'backfill', 'planned'));
  end if;
end
$constraints$;

create index if not exists sheets_publication_date_idx on public.sheets (publication_date);

comment on column public.sheets.closes_at is
  'Automatic closing time (default: Friday 00:00 Asia/Jerusalem before a Sunday publication). The sheet is closed for orders from this moment, without any scheduler.';
comment on column public.sheets.status is
  'Manual state. closed = closed by a user. Effective state: closed when status = closed OR closes_at <= now() (see public.sheet_overview).';

-- =====================================================================
-- 2. Backfill (only missing rows; existing rows are left exactly as they are)
-- =====================================================================
insert into public.sheets (sheet_number, status, status_reason, closed_at, created_via)
select
  used.sheet_number,
  case when keep.sheet_number is null then 'closed' else 'open' end,
  case when keep.sheet_number is null
    then 'גיליון היסטורי — סומן כסגור במעבר למודל הגיליונות'
    else 'גיליון פעיל — נשאר פתוח במעבר למודל הגיליונות' end,
  case when keep.sheet_number is null then pg_catalog.now() end,
  'backfill'
from (
  select distinct pg_catalog.btrim(orders.sheet_number) as sheet_number
  from public.orders
  where pg_catalog.btrim(coalesce(orders.sheet_number, '')) <> ''
) as used
left join sheets_v2_keep_open as keep on keep.sheet_number = used.sheet_number
where not exists (select 1 from public.sheets where sheets.sheet_number = used.sheet_number);

-- =====================================================================
-- 3. Read model
-- =====================================================================
create or replace view public.sheet_overview
with (security_invoker = true)
as
select
  sheets.sheet_number,
  sheets.publication_date,
  sheets.closes_at,
  sheets.description,
  sheets.status,
  (sheets.status = 'closed' or (sheets.closes_at is not null and sheets.closes_at <= pg_catalog.now())) as is_closed,
  case
    when sheets.status = 'closed' then 'manual'
    when sheets.closes_at is not null and sheets.closes_at <= pg_catalog.now() then 'deadline'
  end as closed_by_kind,
  sheets.closed_at,
  sheets.status_reason,
  sheets.reopened_at,
  sheets.created_at,
  sheets.created_via,
  sheets.updated_at,
  pg_catalog.now() as server_now
from public.sheets as sheets;

revoke all on public.sheet_overview from public, anon;
grant select on public.sheet_overview to authenticated;

-- Local wall time ('YYYY-MM-DDTHH:MM' in Israel) → timestamptz. DST is handled by the time zone rules.
create or replace function private.jerusalem_time(p_local text)
returns timestamptz
language plpgsql
stable
set search_path = ''
as $function$
begin
  if p_local is null or pg_catalog.btrim(p_local) = '' then
    return null;
  end if;
  return (p_local::timestamp) at time zone 'Asia/Jerusalem';
exception when others then
  raise exception 'מועד הסגירה אינו תקין.';
end;
$function$;

revoke all on function private.jerusalem_time(text) from public, anon, authenticated;

-- =====================================================================
-- 4. create_sheets_batch — "הוספת גיליונות" (all or nothing)
-- p_sheets: [{ "sheet_number": "141", "publication_date": "2026-11-29",
--              "closes_at_local": "2026-11-27T00:00", "description": "" }, ...]
-- =====================================================================
create or replace function public.create_sheets_batch(p_sheets jsonb, p_idempotency_key uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_cached jsonb;
  v_row jsonb;
  v_index integer := 0;
  v_number text;
  v_numbers text[] := array[]::text[];
  v_publication date;
  v_closes timestamptz;
  v_description text;
  v_existing text;
  v_result jsonb;
begin
  if auth.uid() is null or not private.is_approved_user() then
    raise exception 'החשבון אינו מורשה לבצע פעולה זו.';
  end if;
  if p_sheets is null or pg_catalog.jsonb_typeof(p_sheets) <> 'array'
     or pg_catalog.jsonb_array_length(p_sheets) not between 1 and 60 then
    raise exception 'יש ליצור בין גיליון אחד ל-60 גיליונות בפעולה אחת.';
  end if;

  v_cached := private.claim_business_operation(p_idempotency_key, 'create_sheets_batch', pg_catalog.md5(p_sheets::text));
  if v_cached is not null then
    return v_cached;
  end if;

  -- Validate everything first; nothing is written if any row is invalid.
  for v_row in select value from pg_catalog.jsonb_array_elements(p_sheets) loop
    v_index := v_index + 1;
    v_number := pg_catalog.btrim(coalesce(v_row ->> 'sheet_number', ''));
    if v_number !~ '^[1-9][0-9]{0,8}$' then
      raise exception 'מספר הגיליון בשורה % אינו תקין: ספרות בלבד, מספר חיובי, ללא אפס מוביל.', v_index;
    end if;
    if v_number = any(v_numbers) then
      raise exception 'גיליון % מופיע פעמיים ברשימה.', v_number;
    end if;
    v_numbers := v_numbers || v_number;
    if nullif(v_row ->> 'publication_date', '') is null then
      raise exception 'חסר תאריך פרסום לגיליון %.', v_number;
    end if;
    v_publication := (v_row ->> 'publication_date')::date;
    v_closes := private.jerusalem_time(v_row ->> 'closes_at_local');
    if v_closes is null then
      raise exception 'חסר מועד סגירה לגיליון %.', v_number;
    end if;
    if v_closes >= ((v_publication + 1)::timestamp at time zone 'Asia/Jerusalem') then
      raise exception 'מועד הסגירה של גיליון % חייב להיות לפני סוף יום הפרסום.', v_number;
    end if;
    if v_closes <= pg_catalog.now() then
      raise exception 'מועד הסגירה של גיליון % כבר עבר.', v_number;
    end if;
    if pg_catalog.length(coalesce(v_row ->> 'description', '')) > 200 then
      raise exception 'התיאור של גיליון % ארוך מ-200 תווים.', v_number;
    end if;
  end loop;

  select string_agg(sheets.sheet_number, ', ' order by sheets.sheet_number) into v_existing
  from public.sheets where sheets.sheet_number = any(v_numbers);
  if v_existing is not null then
    raise exception using errcode = '23505',
      message = pg_catalog.format('הגיליונות הבאים כבר קיימים: %s. לא נוצר אף גיליון.', v_existing);
  end if;

  begin
    insert into public.sheets (sheet_number, status, status_reason, publication_date, closes_at, description,
                               created_by, created_via, updated_by)
    select pg_catalog.btrim(item ->> 'sheet_number'), 'open', '', (item ->> 'publication_date')::date,
           private.jerusalem_time(item ->> 'closes_at_local'), pg_catalog.btrim(coalesce(item ->> 'description', '')),
           auth.uid(), 'planned', auth.uid()
    from pg_catalog.jsonb_array_elements(p_sheets) as item;
  exception when unique_violation then
    -- Another user created one of these numbers at the same moment: the whole batch is rolled back.
    raise exception using errcode = '23505',
      message = 'אחד הגיליונות נוצר במקביל על ידי משתמשת אחרת. לא נוצר אף גיליון; יש לרענן ולנסות שוב.';
  end;

  v_result := pg_catalog.jsonb_build_object('created', pg_catalog.to_jsonb(v_numbers), 'count', pg_catalog.cardinality(v_numbers));
  update private.business_operations set response = v_result where idempotency_key = p_idempotency_key;
  return v_result;
end;
$function$;

revoke all on function public.create_sheets_batch(jsonb, uuid) from public, anon;
grant execute on function public.create_sheets_batch(jsonb, uuid) to authenticated;

-- =====================================================================
-- 5. update_sheet_details — publication date, closing time, description
-- A sheet closed by its deadline cannot be reopened by moving the deadline: that is set_sheet_state (reason).
-- =====================================================================
create or replace function public.update_sheet_details(
  p_sheet_number text,
  p_publication_date date,
  p_closes_at_local text,
  p_description text,
  p_expected_updated_at timestamptz
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_sheet public.sheets%rowtype;
  v_closes timestamptz := private.jerusalem_time(p_closes_at_local);
  v_row public.sheets%rowtype;
begin
  if auth.uid() is null or not private.is_approved_user() then
    raise exception 'החשבון אינו מורשה לבצע פעולה זו.';
  end if;
  select * into v_sheet from public.sheets where sheet_number = pg_catalog.btrim(p_sheet_number) for update;
  if not found then
    raise exception 'הגיליון לא נמצא.';
  end if;
  if p_expected_updated_at is null or v_sheet.updated_at is distinct from p_expected_updated_at then
    raise exception using errcode = '40001', message = 'פרטי הגיליון השתנו אצל משתמשת אחרת. רענני ונסי שוב.';
  end if;
  if pg_catalog.length(coalesce(p_description, '')) > 200 then
    raise exception 'התיאור ארוך מ-200 תווים.';
  end if;
  if v_closes is null and v_sheet.closes_at is not null then
    raise exception 'מועד סגירה הוא שדה חובה לגיליון זה.';
  end if;
  if v_closes is not null and p_publication_date is null then
    raise exception 'יש להזין תאריך פרסום.';
  end if;
  if v_closes is not null and v_closes >= ((p_publication_date + 1)::timestamp at time zone 'Asia/Jerusalem') then
    raise exception 'מועד הסגירה חייב להיות לפני סוף יום הפרסום.';
  end if;
  if v_closes is distinct from v_sheet.closes_at and v_sheet.status <> 'closed' then
    if v_sheet.closes_at is not null and v_sheet.closes_at <= pg_catalog.now() then
      raise exception 'הגיליון נסגר במועד הסגירה. כדי לשנות את המועד יש לפתוח אותו מחדש (עם סיבה).';
    end if;
    if v_closes <= pg_catalog.now() then
      raise exception 'מועד הסגירה החדש כבר עבר. לסגירה מיידית יש להשתמש ב"סגירת הגיליון".';
    end if;
  end if;

  update public.sheets
  set publication_date = p_publication_date,
      closes_at = v_closes,
      description = pg_catalog.btrim(coalesce(p_description, '')),
      updated_by = auth.uid()
  where sheet_number = v_sheet.sheet_number
  returning * into v_row;

  return pg_catalog.jsonb_build_object('sheet_number', v_row.sheet_number, 'updated_at', v_row.updated_at);
end;
$function$;

revoke all on function public.update_sheet_details(text, date, text, text, timestamptz) from public, anon;
grant execute on function public.update_sheet_details(text, date, text, text, timestamptz) to authenticated;

-- =====================================================================
-- 6. set_sheet_state — close now / reopen (reason ≥ 3 characters + a new future closing time when the
--    previous one has passed, so a reopened sheet is not closed again immediately).
-- =====================================================================
create or replace function public.set_sheet_state(
  p_sheet_number text,
  p_is_closed boolean,
  p_reason text,
  p_reopen_closes_at_local text,
  p_expected_updated_at timestamptz
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_number text := nullif(pg_catalog.btrim(p_sheet_number), '');
  v_sheet public.sheets%rowtype;
  v_found boolean;
  v_closed boolean;
  v_new_closes timestamptz := private.jerusalem_time(p_reopen_closes_at_local);
  v_row public.sheets%rowtype;
begin
  if auth.uid() is null or not private.is_approved_user() then
    raise exception 'החשבון אינו מורשה לבצע פעולה זו.';
  end if;
  if v_number is null or p_is_closed is null then
    raise exception 'יש לבחור גיליון וסטטוס.';
  end if;

  select * into v_sheet from public.sheets where sheet_number = v_number for update;
  v_found := found;
  if v_found and (p_expected_updated_at is null or v_sheet.updated_at is distinct from p_expected_updated_at) then
    raise exception using errcode = '40001', message = 'סטטוס הגיליון השתנה אצל משתמשת אחרת. רענני ונסי שוב.';
  end if;
  if not v_found and not exists (select 1 from public.orders where pg_catalog.btrim(sheet_number) = v_number) then
    raise exception 'הגיליון לא נמצא.';
  end if;
  v_closed := v_found and (v_sheet.status = 'closed' or (v_sheet.closes_at is not null and v_sheet.closes_at <= pg_catalog.now()));

  if p_is_closed then
    if v_closed then
      raise exception 'הגיליון כבר סגור.';
    end if;
    insert into public.sheets (sheet_number, status, status_reason, closed_at, closed_by, updated_by, created_by, created_via)
    values (v_number, 'closed', coalesce(nullif(pg_catalog.btrim(p_reason), ''), 'סגירת גיליון'), pg_catalog.now(), auth.uid(),
            auth.uid(), auth.uid(), 'status')
    on conflict (sheet_number) do update
      set status = 'closed', status_reason = excluded.status_reason, closed_at = excluded.closed_at,
          closed_by = excluded.closed_by, updated_by = excluded.updated_by
    returning * into v_row;
  else
    if not v_closed then
      raise exception 'הגיליון כבר פתוח.';
    end if;
    if p_reason is null or pg_catalog.length(pg_catalog.btrim(p_reason)) < 3 then
      raise exception 'נדרש הסבר קצר לפתיחה מחדש של גיליון סגור.';
    end if;
    if v_new_closes is null and v_sheet.closes_at is not null and v_sheet.closes_at <= pg_catalog.now() then
      raise exception 'מועד הסגירה של הגיליון עבר. יש לבחור מועד סגירה חדש בעתיד.';
    end if;
    if v_new_closes is not null and v_new_closes <= pg_catalog.now() then
      raise exception 'מועד הסגירה החדש חייב להיות בעתיד.';
    end if;
    update public.sheets
    set status = 'open', status_reason = pg_catalog.btrim(p_reason), closed_at = null, closed_by = null,
        closes_at = coalesce(v_new_closes, closes_at), reopened_at = pg_catalog.now(), reopened_by = auth.uid(),
        updated_by = auth.uid()
    where sheet_number = v_number
    returning * into v_row;
  end if;

  return pg_catalog.jsonb_build_object(
    'sheet_number', v_row.sheet_number, 'status', v_row.status, 'closes_at', v_row.closes_at,
    'is_closed', v_row.status = 'closed' or (v_row.closes_at is not null and v_row.closes_at <= pg_catalog.now()),
    'updated_at', v_row.updated_at);
end;
$function$;

revoke all on function public.set_sheet_state(text, boolean, text, text, timestamptz) from public, anon;
grant execute on function public.set_sheet_state(text, boolean, text, text, timestamptz) to authenticated;

-- The current UI keeps calling set_sheet_status; it now uses the same rules (no reopen past the deadline
-- without a new closing time, which the current UI cannot send: it gets a clear error instead).
create or replace function public.set_sheet_status(
  p_sheet_number text,
  p_is_closed boolean,
  p_reason text,
  p_expected_updated_at timestamptz
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
begin
  return public.set_sheet_state(p_sheet_number, p_is_closed, p_reason, null, p_expected_updated_at);
end;
$function$;

revoke all on function public.set_sheet_status(text, boolean, text, timestamptz) from public, anon;
grant execute on function public.set_sheet_status(text, boolean, text, timestamptz) to authenticated;

commit;

-- Verification (read only)
select
  (select count(*) from public.sheets) as sheets_total,
  (select count(*) from public.sheets where created_via = 'backfill' and status = 'closed') as backfilled_closed,
  (select count(*) from public.sheets where created_via = 'backfill' and status = 'open') as backfilled_open,
  (select string_agg(sheet_number, ', ') from public.sheets where status = 'open') as open_sheets,
  (select count(*) from public.orders o
    where pg_catalog.btrim(coalesce(o.sheet_number, '')) <> ''
      and not exists (select 1 from public.sheets s where s.sheet_number = pg_catalog.btrim(o.sheet_number))) as orders_without_sheet_row;


-- =====================================================================================================
-- supabase-sheets-v2-enforce.sql
-- =====================================================================================================
-- Sheets model v2 — STAGE B: ENFORCEMENT. REQUIRES THE OWNER'S EXPLICIT APPROVAL.
-- Run ONLY after supabase-sheets-v2.sql AND after the new UI (sheet chosen from a list) is published:
-- from this point an order can only be placed in an existing, open sheet. The current (old) UI would get
-- an error when typing a sheet number that does not exist.
--
-- 1. Every order's sheet_number must exist in public.sheets (foreign key; free text is no longer possible).
-- 2. Trigger orders_enforce_open_sheet: a new order, or moving an order to another sheet, is rejected when the
--    target sheet is closed (status = 'closed' or closes_at <= now()). It applies to EVERY write path: the RPCs
--    (create_orders_batch, update_business_order), direct API writes and imports. Payment status, price, notes
--    and credits of existing orders are not affected (the trigger runs only on insert or a sheet_number change).
-- 3. The sheet row is locked (FOR SHARE) while the order is written, so a simultaneous "close now" is
--    serialised: the order is either accepted before the close or rejected after it.
-- Time rule: the check uses the transaction start time (now()). An order submitted before the deadline but
-- committed a fraction of a second after it is accepted. This is intended and documented.
-- Safe to run twice.

begin;

do $preflight$
declare
  v_orphans text;
  v_spaces bigint;
begin
  if not exists (select 1 from pg_catalog.pg_attribute
                 where attrelid = 'public.sheets'::regclass and attname = 'closes_at' and not attisdropped) then
    raise exception 'Run supabase-sheets-v2.sql first.';
  end if;

  select count(*) into v_spaces from public.orders
  where sheet_number is not null and (sheet_number <> pg_catalog.btrim(sheet_number) or pg_catalog.btrim(sheet_number) = '');
  if v_spaces > 0 then
    raise exception '% orders have a sheet number with surrounding spaces or an empty value. They need a separate, approved normalisation first. Nothing was changed.', v_spaces;
  end if;

  select string_agg(distinct o.sheet_number, ', ') into v_orphans
  from public.orders as o
  where o.sheet_number is not null
    and not exists (select 1 from public.sheets as s where s.sheet_number = o.sheet_number);
  if v_orphans is not null then
    raise exception 'Orders use sheet numbers that have no sheet row: %. Decide their status (open/closed) and create them before enforcing. Nothing was changed.', v_orphans;
  end if;
end
$preflight$;

-- 1. Foreign key (validated after creation; the preflight guarantees it passes)
do $fk$
begin
  if not exists (select 1 from pg_catalog.pg_constraint
                 where conrelid = 'public.orders'::regclass and conname = 'orders_sheet_number_fkey') then
    alter table public.orders
      add constraint orders_sheet_number_fkey foreign key (sheet_number)
      references public.sheets (sheet_number) on update restrict on delete restrict not valid;
  end if;
end
$fk$;
alter table public.orders validate constraint orders_sheet_number_fkey;

-- 2. Closed-sheet guard
create or replace function private.enforce_open_sheet()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_status text;
  v_closes timestamptz;
begin
  if new.sheet_number is null then
    return new;
  end if;
  if tg_op = 'UPDATE' and new.sheet_number is not distinct from old.sheet_number then
    return new;
  end if;

  select status, closes_at into v_status, v_closes
  from public.sheets
  where sheet_number = new.sheet_number
  for share;
  if not found then
    raise exception using errcode = '23503',
      message = pg_catalog.format('גיליון %s אינו קיים במערכת. יש לבחור גיליון מהרשימה.', new.sheet_number);
  end if;
  if v_status = 'closed' or (v_closes is not null and v_closes <= pg_catalog.now()) then
    raise exception using errcode = 'HPS01',
      message = pg_catalog.format('גיליון %s סגור להזמנות. יש לבחור גיליון פתוח.', new.sheet_number);
  end if;
  return new;
end;
$function$;

revoke all on function private.enforce_open_sheet() from public, anon, authenticated;

drop trigger if exists orders_enforce_open_sheet on public.orders;
create trigger orders_enforce_open_sheet
  before insert or update of sheet_number on public.orders
  for each row execute function private.enforce_open_sheet();

commit;

-- Verification (read only)
select
  exists (select 1 from pg_catalog.pg_constraint
          where conrelid = 'public.orders'::regclass and conname = 'orders_sheet_number_fkey' and convalidated) as fk_validated,
  exists (select 1 from pg_catalog.pg_trigger
          where tgrelid = 'public.orders'::regclass and tgname = 'orders_enforce_open_sheet' and not tgisinternal) as trigger_installed;


-- =====================================================================================================
-- supabase-business-upgrade-cutover.sql
-- =====================================================================================================
-- PHASE 2: revoke direct business-table writes after the RPC-based UI is
-- deployed and tested. Run only during a short write-freeze.
-- This file is transactional. It does not modify customer/order data.

begin;

do $cutover_preflight$
begin
  if pg_catalog.to_regprocedure(
       'public.create_orders_batch(text,jsonb,uuid)'
     ) is null
     or pg_catalog.to_regprocedure(
       'public.update_business_order(text,timestamptz,text,date,text,text,text,numeric,numeric,numeric,uuid,date,boolean,uuid)'
     ) is null
     or pg_catalog.to_regprocedure(
       'public.delete_business_order(text,timestamptz,text,uuid)'
     ) is null
     or pg_catalog.to_regprocedure(
       'public.set_obligation_paid(uuid,boolean,text,timestamptz,uuid)'
     ) is null
     or pg_catalog.to_regprocedure(
       'public.purchase_customer_package(text,uuid,text,numeric,integer,numeric,date,date,jsonb,jsonb,text,uuid)'
     ) is null
     or pg_catalog.to_regprocedure(
       'public.adjust_client_credits(text,numeric,text,uuid)'
     ) is null
     or pg_catalog.to_regprocedure(
       'public.convert_credit_orders_to_cash(jsonb,text,uuid)'
     ) is null then
    raise exception 'Required business RPCs are missing. Do not cut over writes.';
  end if;

  if not exists (
    select 1 from pg_catalog.pg_class as relation
    join pg_catalog.pg_namespace as namespace
      on namespace.oid = relation.relnamespace
    where namespace.nspname = 'public'
      and relation.relname = 'orders'
      and relation.relrowsecurity
      and relation.relforcerowsecurity
  ) or not exists (
    select 1 from pg_catalog.pg_class as relation
    join pg_catalog.pg_namespace as namespace
      on namespace.oid = relation.relnamespace
    where namespace.nspname = 'public'
      and relation.relname = 'payments'
      and relation.relrowsecurity
      and relation.relforcerowsecurity
  ) then
    raise exception 'RLS and FORCE RLS are required before the write cutover.';
  end if;
end;
$cutover_preflight$;

revoke all on table public.orders, public.payments
  from public, anon, authenticated;
grant select on table public.orders, public.payments to authenticated;

-- Table-level REVOKE does not clear separately granted column privileges.
do $column_privileges$
declare
  v_table text;
  v_column text;
begin
  foreach v_table in array array['orders', 'payments']
  loop
    for v_column in
      select attribute.attname
      from pg_catalog.pg_attribute as attribute
      where attribute.attrelid =
        pg_catalog.to_regclass('public.' || v_table)
        and attribute.attnum > 0
        and not attribute.attisdropped
    loop
      execute pg_catalog.format(
        'revoke insert (%I) on table public.%I from public, anon, authenticated',
        v_column, v_table
      );
      execute pg_catalog.format(
        'revoke update (%I) on table public.%I from public, anon, authenticated',
        v_column, v_table
      );
      execute pg_catalog.format(
        'revoke references (%I) on table public.%I from public, anon, authenticated',
        v_column, v_table
      );
    end loop;
  end loop;
end;
$column_privileges$;

do $verify_cutover$
begin
  if has_table_privilege('anon', 'public.orders', 'SELECT')
     or has_table_privilege('anon', 'public.payments', 'SELECT')
     or has_table_privilege('authenticated', 'public.orders', 'INSERT')
     or has_table_privilege('authenticated', 'public.orders', 'UPDATE')
     or has_table_privilege('authenticated', 'public.orders', 'DELETE')
     or has_table_privilege('authenticated', 'public.orders', 'TRUNCATE')
     or has_table_privilege('authenticated', 'public.payments', 'INSERT')
     or has_table_privilege('authenticated', 'public.payments', 'UPDATE')
     or has_table_privilege('authenticated', 'public.payments', 'DELETE')
     or has_table_privilege('authenticated', 'public.payments', 'TRUNCATE')
     or exists (
       select 1
       from pg_catalog.pg_attribute as attribute
       where attribute.attrelid in (
         'public.orders'::regclass, 'public.payments'::regclass
       )
         and attribute.attnum > 0
         and not attribute.attisdropped
         and (
           has_column_privilege(
             'authenticated', attribute.attrelid, attribute.attname, 'INSERT'
           )
           or has_column_privilege(
             'authenticated', attribute.attrelid, attribute.attname, 'UPDATE'
           )
         )
     ) then
    raise exception 'Direct table or column write privileges remain after cutover.';
  end if;
end;
$verify_cutover$;

commit;
